/* Tiny WebAudio engine: all music + SFX synthesized, no downloads. */

const MIDI = (m) => 440 * Math.pow(2, (m - 69) / 12);

class AudioEngine {
  constructor() {
    this.ctx = null;
    this.enabled = true;
    this.master = null;
    this.sfxGain = null;
    this.musicGain = null;
    this.musicTimer = null;
    this.step = 0;
    this.nextNoteTime = 0;
    this.noiseBuf = null;
    this.musicPlaying = false;
    this.tempo = 112;
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume();
      return;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    try {
      this.ctx = new AC();
      this.master = this.ctx.createGain();
      this.master.gain.value = this.enabled ? 0.9 : 0;
      this.master.connect(this.ctx.destination);
      this.sfxGain = this.ctx.createGain();
      this.sfxGain.gain.value = 0.55;
      this.sfxGain.connect(this.master);
      this.musicGain = this.ctx.createGain();
      this.musicGain.gain.value = 0.16;
      this.musicGain.connect(this.master);
      this.noiseBuf = this.makeNoise(1.2);
    } catch (e) { /* audio unavailable */ }
  }

  makeNoise(seconds) {
    const len = Math.floor(this.ctx.sampleRate * seconds);
    const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = buf.getChannelData(0);
    for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;
    return buf;
  }

  setEnabled(on) {
    this.enabled = !!on;
    if (this.master && this.ctx) {
      this.master.gain.cancelScheduledValues(this.ctx.currentTime);
      this.master.gain.setTargetAtTime(on ? 0.9 : 0, this.ctx.currentTime, 0.05);
    }
    if (on) this.init();
  }

  tone({ freq = 440, endFreq = null, dur = 0.15, type = 'sine', vol = 0.3, delay = 0, dest = null, attack = 0.005 }) {
    if (!this.ctx || !this.enabled) return;
    const t = this.ctx.currentTime + delay;
    const osc = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t);
    if (endFreq) osc.frequency.exponentialRampToValueAtTime(Math.max(20, endFreq), t + dur);
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(vol, t + attack);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    osc.connect(g);
    g.connect(dest || this.sfxGain);
    osc.start(t);
    osc.stop(t + dur + 0.02);
  }

  noise({ dur = 0.2, vol = 0.25, freq = 1200, q = 1, type = 'bandpass', delay = 0, dest = null, sweep = null }) {
    if (!this.ctx || !this.enabled) return;
    const t = this.ctx.currentTime + delay;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuf;
    const filter = this.ctx.createBiquadFilter();
    filter.type = type;
    filter.frequency.setValueAtTime(freq, t);
    if (sweep) filter.frequency.exponentialRampToValueAtTime(Math.max(60, sweep), t + dur);
    filter.Q.value = q;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(vol, t + 0.01);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    src.connect(filter); filter.connect(g); g.connect(dest || this.sfxGain);
    src.start(t); src.stop(t + dur + 0.02);
  }

  play(name) {
    if (!this.ctx || !this.enabled) return;
    switch (name) {
      case 'click':
        this.tone({ freq: 520, endFreq: 720, dur: 0.06, type: 'square', vol: 0.08 });
        break;
      case 'pop':
        this.tone({ freq: 300, endFreq: 500, dur: 0.08, type: 'triangle', vol: 0.2 });
        break;
      case 'coin':
        this.tone({ freq: 880, dur: 0.08, type: 'triangle', vol: 0.2 });
        this.tone({ freq: 1320, dur: 0.16, type: 'triangle', vol: 0.18, delay: 0.07 });
        break;
      case 'bounce':
        this.tone({ freq: 190, endFreq: 70, dur: 0.16, type: 'sine', vol: 0.5 });
        this.noise({ dur: 0.05, vol: 0.1, freq: 500, type: 'lowpass' });
        break;
      case 'pass':
        this.noise({ dur: 0.14, vol: 0.13, freq: 900, sweep: 2600, type: 'bandpass', q: 1.2 });
        break;
      case 'rim':
        this.tone({ freq: 320, endFreq: 210, dur: 0.22, type: 'square', vol: 0.12 });
        this.noise({ dur: 0.18, vol: 0.16, freq: 2600, q: 6 });
        break;
      case 'swish':
        this.noise({ dur: 0.22, vol: 0.22, freq: 3200, sweep: 1400, type: 'highpass' });
        this.tone({ freq: 1500, endFreq: 2200, dur: 0.12, type: 'sine', vol: 0.1, delay: 0.03 });
        break;
      case 'cheer': {
        const t = this.ctx.currentTime;
        const src = this.ctx.createBufferSource(); src.buffer = this.noiseBuf;
        const f = this.ctx.createBiquadFilter(); f.type = 'bandpass'; f.frequency.value = 900; f.Q.value = 0.6;
        const g = this.ctx.createGain();
        g.gain.setValueAtTime(0.0001, t);
        g.gain.exponentialRampToValueAtTime(0.22, t + 0.12);
        g.gain.exponentialRampToValueAtTime(0.0001, t + 1.15);
        src.connect(f); f.connect(g); g.connect(this.sfxGain);
        src.start(t); src.stop(t + 1.2);
        for (let i = 0; i < 7; i++) {
          this.noise({ dur: 0.07, vol: 0.09, freq: 1400 + Math.random() * 900, q: 2, delay: 0.05 + Math.random() * 0.8 });
        }
        break;
      }
      case 'whistle':
        this.tone({ freq: 2100, endFreq: 2300, dur: 0.18, type: 'sine', vol: 0.12 });
        this.tone({ freq: 2400, endFreq: 2500, dur: 0.3, type: 'sine', vol: 0.1, delay: 0.2 });
        break;
      case 'buzzer':
        this.tone({ freq: 170, dur: 0.7, type: 'square', vol: 0.16 });
        this.tone({ freq: 173, dur: 0.7, type: 'sawtooth', vol: 0.1 });
        break;
      case 'steal':
        this.noise({ dur: 0.1, vol: 0.22, freq: 1800, sweep: 500, type: 'bandpass' });
        this.tone({ freq: 640, endFreq: 300, dur: 0.12, type: 'square', vol: 0.12 });
        break;
      case 'block':
        this.tone({ freq: 120, endFreq: 55, dur: 0.22, type: 'square', vol: 0.3 });
        this.noise({ dur: 0.12, vol: 0.2, freq: 300, type: 'lowpass' });
        break;
      case 'score':
        this.play('swish');
        this.play('cheer');
        this.tone({ freq: 660, dur: 0.1, type: 'triangle', vol: 0.14, delay: 0.05 });
        this.tone({ freq: 990, dur: 0.18, type: 'triangle', vol: 0.14, delay: 0.16 });
        break;
      case 'dunk':
        this.tone({ freq: 100, endFreq: 45, dur: 0.4, type: 'sine', vol: 0.45 });
        this.noise({ dur: 0.3, vol: 0.25, freq: 260, type: 'lowpass' });
        this.play('cheer');
        break;
      case 'win':
        [523, 659, 784, 1047].forEach((f, i) => this.tone({ freq: f, dur: 0.22, type: 'triangle', vol: 0.18, delay: i * 0.12 }));
        this.play('cheer');
        break;
      case 'lose':
        [392, 349, 294, 262].forEach((f, i) => this.tone({ freq: f, dur: 0.24, type: 'sine', vol: 0.16, delay: i * 0.15 }));
        break;
      case 'card':
        [784, 988, 1175, 1568].forEach((f, i) => this.tone({ freq: f, dur: 0.14, type: 'triangle', vol: 0.13, delay: i * 0.07 }));
        break;
      case 'upgrade':
        [523, 784, 1047].forEach((f, i) => this.tone({ freq: f, dur: 0.12, type: 'square', vol: 0.1, delay: i * 0.07 }));
        break;
      case 'trial':
        [659, 880, 1109, 1319].forEach((f, i) => this.tone({ freq: f, dur: 0.3, type: 'triangle', vol: 0.16, delay: i * 0.11 }));
        this.play('cheer');
        break;
      default: break;
    }
  }

  startMusic() {
    this.init();
    if (!this.ctx || this.musicPlaying) return;
    this.musicPlaying = true;
    this.step = 0;
    this.nextNoteTime = this.ctx.currentTime + 0.1;
    this.musicTimer = setInterval(() => this.schedule(), 120);
  }

  stopMusic() {
    this.musicPlaying = false;
    if (this.musicTimer) clearInterval(this.musicTimer);
    this.musicTimer = null;
  }

  schedule() {
    if (!this.ctx || !this.musicPlaying) return;
    const spb = 60 / this.tempo / 2; // eighth notes
    while (this.nextNoteTime < this.ctx.currentTime + 0.35) {
      this.playStep(this.step, this.nextNoteTime - this.ctx.currentTime);
      this.nextNoteTime += spb;
      this.step = (this.step + 1) % 32;
    }
  }

  playStep(step, delay) {
    const t = Math.max(0, delay);
    const bassNotes = [36, 36, 45, 36, 41, 41, 43, 43]; // C C A C F F G G
    const chordTones = [
      [60, 64, 67], [60, 64, 67], [57, 60, 64], [60, 64, 67],
      [53, 57, 60], [53, 57, 60], [55, 59, 62], [55, 59, 62]
    ];
    const bar = Math.floor(step / 4) % 8;
    const beat = step % 4;
    if (beat === 0) {
      this.tone({ freq: MIDI(bassNotes[bar]), dur: 0.32, type: 'triangle', vol: 0.22, delay: t, dest: this.musicGain });
    }
    if (beat === 2) {
      this.tone({ freq: MIDI(bassNotes[bar] + 12), dur: 0.18, type: 'triangle', vol: 0.1, delay: t, dest: this.musicGain });
    }
    const chord = chordTones[bar];
    if (beat % 2 === 0) {
      const note = chord[(step + bar) % chord.length] + 12;
      this.tone({ freq: MIDI(note), dur: 0.16, type: 'square', vol: 0.045, delay: t, dest: this.musicGain });
    }
    if (beat === 1 || beat === 3) {
      this.noise({ dur: 0.035, vol: 0.03, freq: 7000, type: 'highpass', delay: t, dest: this.musicGain });
    }
    if (step === 0 || step === 16) {
      this.noise({ dur: 0.12, vol: 0.05, freq: 180, type: 'lowpass', delay: t, dest: this.musicGain });
    }
  }
}

export const audio = new AudioEngine();

import { MESSAGES } from './data.js';

const W = 600;
const H = 900;
const TOP_HOOP = { x: 300, y: 92 };
const BOTTOM_HOOP = { x: 300, y: 808 };
const RIM_R = 22;
const THREE_R = 225;
const PAD_TOP = 72;
const PAD_BOTTOM = 146;

const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const dist = (a, b) => Math.hypot(a.x - b.x, a.y - b.y);
const norm = (x, y) => { const l = Math.hypot(x, y) || 1; return { x: x / l, y: y / l }; };
const rand = (a, b) => a + Math.random() * (b - a);
const pick = (arr) => arr[Math.floor(Math.random() * arr.length)];

function roundRect(ctx, x, y, w, h, r) {
  const rr = Math.min(r, w / 2, h / 2);
  ctx.beginPath();
  ctx.moveTo(x + rr, y);
  ctx.arcTo(x + w, y, x + w, y + h, rr);
  ctx.arcTo(x + w, y + h, x, y + h, rr);
  ctx.arcTo(x, y + h, x, y, rr);
  ctx.arcTo(x, y, x + w, y, rr);
  ctx.closePath();
}

export class Game {
  constructor(canvas, opts = {}) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d');
    this.opts = opts;
    this.onHud = opts.onHud || (() => {});
    this.onEnd = opts.onEnd || (() => {});
    this.audio = opts.audio || null;
    this.jersey = opts.jersey;
    this.court = opts.court;
    this.opp = opts.opponent;
    this.league = opts.league;
    this.difficulty = opts.difficulty || 1;
    this.state = 'idle';
    this.move = { x: 0, y: 0 };
    this.players = [];
    this.particles = [];
    this.floaters = [];
    this.scorers = {};
    this.shots = 0;
    this.makes = 0;
    this.steals = 0;
    this.blocks = 0;
    this.score = [0, 0];
    this.time = 120;
    this.shotClock = 14;
    this.overtime = false;
    this.freeze = 0;
    this.pendingPossession = 0;
    this.endTimer = 0;
    this.reported = false;
    this.messageData = null;
    this.shakeTime = 0;
    this.shakeMag = 0;
    this.flash = 0;
    this.rimFlash = 0;
    this.elapsed = 0;
    this.hudClock = 0;
    this.active = null;
    this.activeSwitchClock = 0;
    this.ball = { pos: { x: 300, y: 640 }, vel: { x: 0, y: 0 }, z: 0, vz: 0, carrier: null, flight: null, pickupCd: 0, dead: false };
    this.cw = 0; this.ch = 0; this.dpr = 1;
    this.scale = 1; this.ox = 0; this.oy = 0; this.camY = 0; this.viewH = H;
    this._raf = null;
    this._last = 0;
    this._boundResize = () => this.resize();
    this._boundPointerDown = (e) => this.pointerDown(e);
    this._boundPointerUp = (e) => this.pointerUp(e);
    this._boundVisibility = () => {
      if (document.hidden && this.state === 'live') {
        this.pause();
        this.opts.onAutoPause?.();
      }
    };
  }

  /* ---------------- setup ---------------- */

  start() {
    this.buildTeams();
    this.setupPossession(0);
    this.state = 'intro';
    this.intro = 3.1;
    this.time = 120;
    this.shotClock = 14;
    this.overtime = false;
    this.freeze = 0;
    this.score = [0, 0];
    this.elapsed = 0;
    this.messageData = null;
    this.reported = false;
    this.particles = [];
    this.floaters = [];
    this.resize();
    window.addEventListener('resize', this._boundResize);
    window.addEventListener('orientationchange', this._boundResize);
    if (window.ResizeObserver) {
      this._ro = new ResizeObserver(() => this.resize());
      this._ro.observe(this.canvas.parentElement);
    }
    this.canvas.addEventListener('pointerdown', this._boundPointerDown);
    this.canvas.addEventListener('pointerup', this._boundPointerUp);
    document.addEventListener('visibilitychange', this._boundVisibility);
    this.last = performance.now();
    this.loop(this.last);
  }

  destroy() {
    if (this._raf) cancelAnimationFrame(this._raf);
    this._raf = null;
    window.removeEventListener('resize', this._boundResize);
    window.removeEventListener('orientationchange', this._boundResize);
    this.canvas.removeEventListener('pointerdown', this._boundPointerDown);
    this.canvas.removeEventListener('pointerup', this._boundPointerUp);
    document.removeEventListener('visibilitychange', this._boundVisibility);
    if (this._ro) this._ro.disconnect();
    this.state = 'idle';
  }

  buildTeams() {
    const skins = ['#F2B27E', '#C98A5B', '#8D5524', '#E8A76B', '#F6C79C'];
    const hairs = ['#2B1B12', '#1B1210', '#24140D', '#3A2416', '#4A2C1A'];
    const roles = ['PG', 'SG', 'SF', 'PF', 'C'];
    const names1 = ['Rio', 'Bena', 'Kia', 'Jojo', 'Lala'];
    this.players = [];

    (this.opts.players || []).forEach((p, i) => {
      this.players.push({
        team: 0, idx: i, role: roles[i], name: p.name, number: p.number,
        stats: { ...p.stats }, skin: p.skin || skins[i], hair: p.hair || hairs[i],
        hairStyle: p.hairStyle || 'fade', pos: { x: 300, y: 650 }, vel: { x: 0, y: 0 },
        facing: { x: 0, y: -1 }, anim: Math.random() * 6, stun: 0, stealCd: 0, shootCd: 0,
        passCd: 0, aiTimer: 0, jump: 0, blockWindow: 0, dash: 0, dribble: 0, moving: false
      });
    });

    const base = this.opp?.rating || 60;
    const offsets = [
      { speed: 2, shoot: 0, dribble: 4, defense: -2 },
      { speed: 0, shoot: 4, dribble: 0, defense: 0 },
      { speed: 3, shoot: -2, dribble: 2, defense: -1 },
      { speed: -3, shoot: -1, dribble: -2, defense: 4 },
      { speed: -4, shoot: 0, dribble: -1, defense: 5 }
    ];
    offsets.forEach((o, i) => {
      const s = {
        speed: clamp(Math.round(base + o.speed + rand(-3, 3)), 30, 99),
        shoot: clamp(Math.round(base + o.shoot + rand(-3, 3)), 30, 99),
        dribble: clamp(Math.round(base + o.dribble + rand(-3, 3)), 30, 99),
        defense: clamp(Math.round(base + o.defense + rand(-3, 3)), 30, 99)
      };
      this.players.push({
        team: 1, idx: i, role: roles[i], name: names1[i], number: [4, 8, 12, 21, 33][i],
        stats: s, skin: skins[(i + 2) % skins.length], hair: hairs[(i + 1) % hairs.length],
        hairStyle: ['fade', 'curly', 'spiky', 'bun', 'pony'][i],
        pos: { x: 300, y: 250 }, vel: { x: 0, y: 0 }, facing: { x: 0, y: 1 },
        anim: Math.random() * 6, stun: 0, stealCd: 0, shootCd: 0, passCd: 0,
        aiTimer: 0, jump: 0, blockWindow: 0, dash: 0, dribble: 0, moving: false
      });
    });
  }

  maxSpeed(p) {
    return 146 + p.stats.speed * 0.6;
  }

  attackHoop(team) { return team === 0 ? TOP_HOOP : BOTTOM_HOOP; }
  ownHoop(team) { return team === 0 ? BOTTOM_HOOP : TOP_HOOP; }

  setupPossession(team) {
    const offense = this.players.filter((p) => p.team === team);
    const defense = this.players.filter((p) => p.team !== team);
    const offSpots = team === 0
      ? [{ x: 300, y: 655 }, { x: 165, y: 710 }, { x: 435, y: 710 }, { x: 175, y: 790 }, { x: 425, y: 790 }]
      : [{ x: 300, y: 245 }, { x: 165, y: 190 }, { x: 435, y: 190 }, { x: 175, y: 110 }, { x: 425, y: 110 }];
    const defSpots = team === 0
      ? [{ x: 300, y: 430 }, { x: 170, y: 385 }, { x: 430, y: 385 }, { x: 150, y: 310 }, { x: 450, y: 310 }]
      : [{ x: 300, y: 470 }, { x: 170, y: 515 }, { x: 430, y: 515 }, { x: 150, y: 590 }, { x: 450, y: 590 }];

    offense.forEach((p, i) => {
      p.pos.x = offSpots[i].x; p.pos.y = offSpots[i].y;
      p.vel.x = 0; p.vel.y = 0; p.stun = 0; p.jump = 0;
      p.facing = { x: 0, y: team === 0 ? -1 : 1 };
    });
    defense.forEach((p, i) => {
      p.pos.x = defSpots[i].x; p.pos.y = defSpots[i].y;
      p.vel.x = 0; p.vel.y = 0; p.stun = 0; p.jump = 0;
      p.facing = { x: 0, y: team === 0 ? 1 : -1 };
    });

    const carrier = offense[0];
    this.ball.carrier = carrier;
    this.ball.flight = null;
    this.ball.dead = false;
    this.ball.z = 0;
    this.ball.vz = 0;
    this.ball.vel = { x: 0, y: 0 };
    this.ball.pickupCd = 0;
    this.ball.pos = { x: carrier.pos.x, y: carrier.pos.y };
    this.possTeam = team;
    this.shotClock = 14;
    this.freeze = 0;
    this.pendingPossession = null;
    this.setActive(team === 0 ? carrier : this.nearestTeamPlayer(0, carrier.pos));
  }

  setActive(p) {
    if (!p) return;
    this.active = p;
    this.activeSwitchClock = 0;
  }

  nearestTeamPlayer(team, pos) {
    let best = null; let bd = Infinity;
    this.players.forEach((p) => {
      if (p.team !== team) return;
      const d = dist(p.pos, pos);
      if (d < bd) { bd = d; best = p; }
    });
    return best;
  }

  /* ---------------- loop ---------------- */

  loop = (ts) => {
    this._raf = requestAnimationFrame(this.loop);
    const dtRaw = Math.min(0.05, Math.max(0, (ts - this.last) / 1000));
    this.last = ts;
    if (this.state === 'idle') return;
    if (this.state !== 'paused') this.update(dtRaw);
    this.render();
    this.hudClock -= dtRaw;
    if (this.hudClock <= 0) {
      this.hudClock = 0.08;
      this.pushHud();
    }
  };

  pushHud() {
    const hasBall = this.ball.carrier && this.ball.carrier.team === 0;
    let label = 'STEAL';
    if (hasBall) label = 'DRIBBLE';
    else if (this.ball.flight?.type === 'shot') label = 'BLOK';
    this.onHud({
      score: [...this.score],
      time: Math.max(0, this.time),
      shotClock: Math.max(0, this.shotClock),
      state: this.state,
      label,
      overtime: this.overtime,
      possession: this.ball.carrier ? this.ball.carrier.team : (this.ball.flight ? this.ball.flight.team : null)
    });
  }

  update(dt) {
    this.elapsed += dt;
    if (this.state === 'ended') {
      this.endTimer -= dt;
      this.updateParticles(dt);
      this.updateEffects(dt);
      if (this.endTimer <= 0 && !this.reported) {
        this.reported = true;
        this.report();
      }
      return;
    }
    if (this.state === 'intro') {
      this.intro -= dt;
      this.updateEffects(dt);
      if (this.intro <= 0) {
        this.state = 'live';
        this.message('MULAI!', 1);
        this.sound('whistle');
      }
      return;
    }
    if (this.state !== 'live') return;

    this.updateEffects(dt);

    if (this.freeze > 0) {
      this.freeze -= dt;
      this.updateParticles(dt);
      if (this.freeze <= 0 && this.pendingPossession != null) {
        this.setupPossession(this.pendingPossession);
      }
      return;
    }

    this.time -= dt;
    this.shotClock -= dt;
    this.updatePlayers(dt);
    this.updateBall(dt);
    this.updateActiveLogic(dt);
    this.updateParticles(dt);

    if (this.shotClock <= 0) {
      this.message('SHOT CLOCK!', 0.9);
      this.sound('buzzer');
      this.setupPossession(1 - this.possTeam);
    }

    if (this.time <= 0) {
      this.time = 0;
      if (this.score[0] === this.score[1] && !this.overtime) {
        this.overtime = true;
        this.time = 20;
        this.message('OVERTIME!', 1.6);
        this.sound('whistle');
      } else {
        this.endMatch();
      }
    }
  }

  updateEffects(dt) {
    if (this.shakeTime > 0) this.shakeTime -= dt;
    if (this.flash > 0) this.flash = Math.max(0, this.flash - dt * 2.5);
    if (this.rimFlash > 0) this.rimFlash = Math.max(0, this.rimFlash - dt * 2.2);
    if (this.messageData) {
      this.messageData.t -= dt;
      if (this.messageData.t <= 0) this.messageData = null;
    }
  }

  /* ---------------- players ---------------- */

  updatePlayers(dt) {
    const b = this.ball;

    this.players.forEach((p) => {
      if (p.stun > 0) p.stun -= dt;
      if (p.stealCd > 0) p.stealCd -= dt;
      if (p.shootCd > 0) p.shootCd -= dt;
      if (p.passCd > 0) p.passCd -= dt;
      if (p.jump > 0) p.jump -= dt;
      if (p.blockWindow > 0) p.blockWindow -= dt;
      if (p.dash > 0) p.dash -= dt;

      if (p === this.active && p.team === 0) {
        this.updateUserPlayer(p, dt);
      } else {
        this.updateAI(p, dt);
      }
    });

    // separation
    for (let i = 0; i < this.players.length; i++) {
      for (let j = i + 1; j < this.players.length; j++) {
        const a = this.players[i]; const c = this.players[j];
        const dx = c.pos.x - a.pos.x; const dy = c.pos.y - a.pos.y;
        const d = Math.hypot(dx, dy);
        const min = 42;
        if (d > 0 && d < min) {
          const push = (min - d) / 2;
          const nx = dx / d; const ny = dy / d;
          const aw = a === this.active ? 0.35 : 1;
          const cw = c === this.active ? 0.35 : 1;
          a.pos.x -= nx * push * aw; a.pos.y -= ny * push * aw;
          c.pos.x += nx * push * cw; c.pos.y += ny * push * cw;
        }
      }
    }

    this.players.forEach((p) => {
      p.pos.x = clamp(p.pos.x, 26, W - 26);
      p.pos.y = clamp(p.pos.y, 28, H - 28);
      const sp = Math.hypot(p.vel.x, p.vel.y);
      p.moving = sp > 12;
      p.anim += dt * (p.moving ? 2 + sp / 40 : 0);
      if (p.moving) p.facing = norm(p.vel.x, p.vel.y);
      else if (b.carrier === p) {
        const h = this.attackHoop(p.team);
        p.facing = norm(h.x - p.pos.x, h.y - p.pos.y);
      }
      if (p.carrierDribble == null) p.carrierDribble = 0;
      if (b.carrier === p) p.dribble += dt * (p.moving ? 11 : 7);
    });
  }

  updateUserPlayer(p, dt) {
    let mx = this.move.x; let my = this.move.y;
    const len = Math.hypot(mx, my);
    if (len > 1) { mx /= len; my /= len; }
    const max = this.maxSpeed(p) * (p.dash > 0 ? 1.55 : 1) * (p.stun > 0 ? 0.15 : 1);
    const tvx = mx * max; const tvy = my * max;
    const k = Math.min(1, dt * 13);
    p.vel.x += (tvx - p.vel.x) * k;
    p.vel.y += (tvy - p.vel.y) * k;
    p.pos.x += p.vel.x * dt;
    p.pos.y += p.vel.y * dt;
  }

  updateAI(p, dt) {
    if (p.stun > 0) {
      p.vel.x *= 0.9; p.vel.y *= 0.9;
      p.pos.x += p.vel.x * dt; p.pos.y += p.vel.y * dt;
      return;
    }
    const b = this.ball;
    const carrier = b.carrier;
    const possTeam = carrier ? carrier.team : (b.flight ? b.flight.team : null);

    if (carrier === p) {
      this.aiCarrier(p, dt);
    } else if (possTeam === p.team) {
      this.aiOffense(p, dt);
    } else if (possTeam != null) {
      this.aiDefense(p, dt);
    } else {
      this.aiLoose(p, dt);
    }
  }

  aiCarrier(p, dt) {
    const hoop = this.attackHoop(p.team);
    const d = dist(p.pos, hoop);
    const opponents = this.players.filter((q) => q.team !== p.team);
    let nearest = null; let nd = Infinity;
    opponents.forEach((q) => { const dd = dist(p.pos, q.pos); if (dd < nd) { nd = dd; nearest = q; } });

    p.aiTimer -= dt;
    if (p.aiTimer <= 0) {
      p.aiTimer = 0.35 + Math.random() * 0.55;
      const pressured = nd < 58;
      const wantShot = d < 260 && (nd > 52 || this.shotClock < 4 || d < 110);
      if (wantShot && p.shootCd <= 0) {
        const chance = d < 120 ? 0.95 : pressured ? 0.35 : 0.62;
        if (Math.random() < chance) { this.shoot(p, true); return; }
      }
      if (pressured && p.passCd <= 0 && Math.random() < 0.55) {
        this.pass(p, true);
        return;
      }
    }

    const dirToHoop = norm(hoop.x - p.pos.x, hoop.y - p.pos.y);
    let target = { x: hoop.x + dirToHoop.x * 0, y: hoop.y + (p.team === 0 ? 88 : -88) };
    target.x += Math.sin(this.elapsed * 1.1 + p.idx * 2) * 38;

    if (nd < 56 && nearest) {
      const away = norm(p.pos.x - nearest.pos.x, p.pos.y - nearest.pos.y);
      target.x = p.pos.x + away.x * 70 + dirToHoop.x * 35;
      target.y = p.pos.y + away.y * 70 + dirToHoop.y * 35;
    }
    this.moveTo(p, target, this.maxSpeed(p) * (this.difficulty > 1 ? 1.02 : 1), dt);
  }

  aiOffense(p, dt) {
    const hoop = this.attackHoop(p.team);
    const spots = this.offenseSpots(p.team);
    const spot = spots[p.idx] || spots[0];
    const shot = this.ball.flight?.type === 'shot' && this.ball.flight.team === p.team;
    let target = spot;
    if (shot) {
      target = { x: hoop.x + (p.idx - 2) * 42, y: hoop.y + (p.team === 0 ? 50 : -50) };
    }
    this.moveTo(p, target, this.maxSpeed(p) * 0.92, dt);
  }

  aiDefense(p, dt) {
    const own = this.ownHoop(p.team);
    const carrier = this.ball.carrier;
    const threat = carrier ? carrier.pos : this.ball.pos;
    const mates = this.players.filter((q) => q.team === p.team && q !== this.active);
    let closest = null; let cd = Infinity;
    mates.forEach((q) => { const d = dist(q.pos, threat); if (d < cd) { cd = d; closest = q; } });

    if (p === closest && carrier) {
      const toOwn = norm(own.x - carrier.pos.x, own.y - carrier.pos.y);
      const target = { x: carrier.pos.x + toOwn.x * 34, y: carrier.pos.y + toOwn.y * 34 };
      this.moveTo(p, target, this.maxSpeed(p) * 1.02, dt);
      if (dist(p.pos, carrier.pos) < 46 && p.stealCd <= 0 && Math.random() < dt * 0.7 * this.difficulty) {
        this.attemptSteal(p, carrier, true);
      }
      return;
    }

    const opps = this.players.filter((q) => q.team !== p.team);
    const mark = opps[p.idx] || opps[0];
    if (!mark) return;
    const toOwn = norm(own.x - mark.pos.x, own.y - mark.pos.y);
    const target = { x: mark.pos.x + toOwn.x * 48, y: mark.pos.y + toOwn.y * 48 };
    this.moveTo(p, target, this.maxSpeed(p) * 0.94, dt);

    if (this.ball.carrier && dist(p.pos, this.ball.carrier.pos) < 42 && p.stealCd <= 0 && Math.random() < dt * 0.35 * this.difficulty) {
      this.attemptSteal(p, this.ball.carrier, true);
    }
  }

  aiLoose(p, dt) {
    const ball = this.ball;
    const mates = this.players.filter((q) => q.team === p.team);
    const sorted = mates.slice().sort((a, b) => dist(a.pos, ball.pos) - dist(b.pos, ball.pos));
    const isChaser = sorted.indexOf(p) < 2;
    if (isChaser) {
      const lead = { x: ball.pos.x + ball.vel.x * 0.2, y: ball.pos.y + ball.vel.y * 0.2 };
      this.moveTo(p, lead, this.maxSpeed(p) * 1.06, dt);
    } else {
      const spot = this.defenseSpots(p.team)[p.idx] || this.offenseSpots(p.team)[p.idx];
      this.moveTo(p, spot, this.maxSpeed(p) * 0.8, dt);
    }
  }

  moveTo(p, target, speed, dt) {
    const dx = target.x - p.pos.x; const dy = target.y - p.pos.y;
    const d = Math.hypot(dx, dy);
    if (d > 3) {
      const tvx = (dx / d) * speed; const tvy = (dy / d) * speed;
      const k = Math.min(1, dt * 7);
      p.vel.x += (tvx - p.vel.x) * k;
      p.vel.y += (tvy - p.vel.y) * k;
    } else {
      p.vel.x *= 0.85; p.vel.y *= 0.85;
    }
    p.pos.x += p.vel.x * dt;
    p.pos.y += p.vel.y * dt;
  }

  offenseSpots(team) {
    if (team === 0) {
      return [{ x: 300, y: 345 }, { x: 118, y: 295 }, { x: 482, y: 295 }, { x: 195, y: 160 }, { x: 405, y: 160 }];
    }
    return [{ x: 300, y: 555 }, { x: 118, y: 605 }, { x: 482, y: 605 }, { x: 195, y: 740 }, { x: 405, y: 740 }];
  }

  defenseSpots(team) {
    if (team === 0) {
      return [{ x: 300, y: 680 }, { x: 170, y: 735 }, { x: 430, y: 735 }, { x: 150, y: 810 }, { x: 450, y: 810 }];
    }
    return [{ x: 300, y: 220 }, { x: 170, y: 165 }, { x: 430, y: 165 }, { x: 150, y: 90 }, { x: 450, y: 90 }];
  }

  updateActiveLogic(dt) {
    const b = this.ball;
    if (b.carrier && b.carrier.team === 0) {
      if (this.active !== b.carrier) this.setActive(b.carrier);
      return;
    }
    if (b.flight && b.flight.type === 'pass' && b.flight.target.team === 0) {
      if (this.active !== b.flight.target) this.setActive(b.flight.target);
      return;
    }
    if (!b.carrier && !b.flight && this.active && this.active.team === 0) {
      this.activeSwitchClock += dt;
      if (this.activeSwitchClock > 0.45) {
        this.activeSwitchClock = 0;
        const nearest = this.nearestTeamPlayer(0, b.pos);
        if (nearest && nearest !== this.active && dist(nearest.pos, b.pos) + 70 < dist(this.active.pos, b.pos)) {
          this.setActive(nearest);
        }
      }
    }
  }

  /* ---------------- ball ---------------- */

  updateBall(dt) {
    const b = this.ball;
    if (b.pickupCd > 0) b.pickupCd -= dt;

    if (b.carrier) {
      const c = b.carrier;
      const off = 18;
      b.pos.x = c.pos.x + c.facing.x * off;
      b.pos.y = c.pos.y + c.facing.y * off;
      b.z = c.moving ? Math.abs(Math.sin(c.dribble)) * 13 : 7;
      return;
    }

    if (b.flight) {
      const f = b.flight;
      f.t += dt / f.dur;
      const t = clamp(f.t, 0, 1);
      b.pos.x = f.from.x + (f.to.x - f.from.x) * t;
      b.pos.y = f.from.y + (f.to.y - f.from.y) * t;
      if (f.type === 'shot') {
        b.z = Math.sin(Math.PI * t) * f.apex + (1 - t) * 22;
        // mid-air block check for the user
        const act = this.active;
        if (act && act.team !== f.team && act.blockWindow > 0 && dist(act.pos, b.pos) < 46 && b.z > 30 && b.z < 120) {
          if (Math.random() < 0.5) { this.resolveBlock(act, f); return; }
        }
      } else {
        b.z = Math.sin(Math.PI * t) * f.apex;
        // interception
        const defenders = this.players.filter((q) => q.team !== f.team);
        for (const q of defenders) {
          if (dist(q.pos, b.pos) < 34 && Math.random() < dt * 1.9 * (q.team === 0 ? 1 : this.difficulty)) {
            this.intercept(q, f);
            return;
          }
        }
      }
      if (f.t >= 1) {
        if (f.type === 'pass') this.completePass(f);
        else this.resolveShot(f);
      }
      return;
    }

    // loose ball physics
    if (b.dead) return;
    b.pos.x += b.vel.x * dt;
    b.pos.y += b.vel.y * dt;
    const fr = Math.pow(0.985, dt * 60);
    b.vel.x *= fr; b.vel.y *= fr;
    b.z += b.vz * dt;
    b.vz -= 780 * dt;
    if (b.z < 0) {
      b.z = 0;
      if (Math.abs(b.vz) > 40) {
        b.vz = -b.vz * 0.55;
        if (this.audio && Math.random() < 0.7) this.sound('bounce');
      } else b.vz = 0;
    }
    if (b.pos.x < 30) { b.pos.x = 30; b.vel.x = Math.abs(b.vel.x) * 0.6; }
    if (b.pos.x > W - 30) { b.pos.x = W - 30; b.vel.x = -Math.abs(b.vel.x) * 0.6; }
    if (b.pos.y < 30) { b.pos.y = 30; b.vel.y = Math.abs(b.vel.y) * 0.6; }
    if (b.pos.y > H - 30) { b.pos.y = H - 30; b.vel.y = -Math.abs(b.vel.y) * 0.6; }

    if (b.pickupCd <= 0 && b.z < 26) {
      let best = null; let bd = 34;
      this.players.forEach((p) => {
        const d = dist(p.pos, b.pos);
        if (d < bd && p.stun <= 0) { bd = d; best = p; }
      });
      if (best) this.gainPossession(best);
    }
  }

  gainPossession(p) {
    const b = this.ball;
    b.carrier = p;
    b.flight = null;
    b.dead = false;
    b.z = 0; b.vz = 0;
    b.vel = { x: 0, y: 0 };
    this.possTeam = p.team;
    this.shotClock = 14;
    if (p.team === 0) {
      this.setActive(p);
      this.message('BOLA KITA!', 0.7);
    }
    p.dribble = 0;
    this.sound('bounce');
  }

  /* ---------------- actions ---------------- */

  setMove(x, y) {
    this.move.x = x; this.move.y = y;
  }

  action(name) {
    if (this.state !== 'live') return;
    const a = this.active;
    if (!a || a.team !== 0) return;
    const b = this.ball;
    const hasBall = b.carrier && b.carrier.team === 0;

    if (name === 'pass') {
      if (hasBall) this.pass(b.carrier, false);
      else this.switchDefender();
      return;
    }
    if (name === 'shoot') {
      if (hasBall) this.shoot(b.carrier, false);
      else this.jump(a);
      return;
    }
    if (name === 'steal') {
      if (hasBall) {
        if (a.dash <= 0) {
          a.dash = 0.34;
          a.stealCd = 1.2;
          this.sound('pop');
        }
      } else if (b.carrier && b.carrier.team === 1) {
        if (a.stealCd <= 0) this.attemptSteal(a, b.carrier, false);
      } else {
        this.jump(a);
      }
    }
  }

  jump(p) {
    if (p.jump > 0) return;
    p.jump = 0.42;
    p.blockWindow = 0.62;
    this.sound('pop');
  }

  switchDefender(dir) {
    const mates = this.players.filter((p) => p.team === 0 && p !== this.active);
    if (!mates.length) return;
    let target = null;
    if (dir === 'left' || dir === 'right') {
      const sign = dir === 'left' ? -1 : 1;
      const options = mates.filter((p) => (p.pos.x - this.active.pos.x) * sign > -20);
      target = (options.length ? options : mates).sort((a, b) => Math.abs(a.pos.x - this.active.pos.x) - Math.abs(b.pos.x - this.active.pos.x))[0];
    } else {
      target = mates.sort((a, b) => dist(a.pos, this.ball.pos) - dist(b.pos, this.ball.pos))[0];
    }
    if (target) { this.setActive(target); this.sound('click'); }
  }

  swipe(dir) {
    if (this.state !== 'live') return;
    if (dir === 'up') { this.action('shoot'); return; }
    if (this.ball.carrier && this.ball.carrier.team === 0) {
      this.pass(this.ball.carrier, false, dir);
    } else {
      this.switchDefender(dir);
    }
  }

  choosePassTarget(from, dir, isAI) {
    const mates = this.players.filter((p) => p.team === from.team && p !== from);
    const hoop = this.attackHoop(from.team);
    let best = mates[0]; let bestScore = -Infinity;
    mates.forEach((m) => {
      let score = 0;
      const openness = Math.min(1, (Math.min(...this.players.filter((o) => o.team !== from.team).map((o) => dist(o.pos, m.pos))) || 100) / 160);
      if (dir === 'left') score += (from.pos.x - m.pos.x) * 1.2;
      else if (dir === 'right') score += (m.pos.x - from.pos.x) * 1.2;
      else score += (from.team === 0 ? from.pos.y - m.pos.y : m.pos.y - from.pos.y) * 0.9;
      score += openness * 90;
      score -= dist(from.pos, m.pos) * 0.12;
      if (this.ball.carrier === m) score -= 500;
      if (score > bestScore) { bestScore = score; best = m; }
    });
    if (isAI) {
      const open = mates.slice().sort((a, b) => {
        const oa = Math.min(...this.players.filter((o) => o.team !== from.team).map((o) => dist(o.pos, a.pos)));
        const ob = Math.min(...this.players.filter((o) => o.team !== from.team).map((o) => dist(o.pos, b.pos)));
        return ob - oa;
      });
      if (open[0]) best = open[0];
    }
    return best;
  }

  pass(from, isAI = false, dir = null) {
    if (this.ball.carrier !== from) return;
    const target = this.choosePassTarget(from, dir, isAI);
    if (!target) return;
    const lead = { x: target.pos.x + target.vel.x * 0.12, y: target.pos.y + target.vel.y * 0.12 };
    const d = dist(from.pos, lead);
    this.ball.carrier = null;
    this.ball.flight = {
      type: 'pass', from: { x: from.pos.x, y: from.pos.y }, to: lead,
      target, team: from.team, t: 0, dur: clamp(d / 560, 0.24, 0.7), apex: 30
    };
    this.ball.pickupCd = 0.2;
    this.possTeam = from.team;
    from.passCd = 0.5;
    this.sound('pass');
    if (!isAI && from.team === 0) this.setActive(target);
  }

  completePass(f) {
    const b = this.ball;
    b.flight = null;
    const t = f.target;
    const d = dist(t.pos, b.pos);
    if (d < 95) {
      b.carrier = t;
      b.pos = { x: t.pos.x, y: t.pos.y };
      b.z = 0;
      this.possTeam = t.team;
      if (t.team === 0) { this.setActive(t); this.sound('bounce'); }
    } else {
      b.vel = { x: rand(-80, 80), y: rand(-80, 80) };
      b.z = 10; b.vz = 40; b.pickupCd = 0.25;
    }
  }

  intercept(defender, f) {
    const b = this.ball;
    b.flight = null;
    b.carrier = defender;
    b.z = 0; b.vz = 0;
    this.possTeam = defender.team;
    this.shotClock = 14;
    defender.dribble = 0;
    this.float('INTERCEPT!', b.pos.x, b.pos.y - 45, '#FFD166', 22);
    this.sound('steal');
    if (defender.team === 0) {
      this.setActive(defender);
      this.steals += 1;
    }
    this.shake(4, 0.2);
  }

  shoot(p, isAI = false) {
    if (this.ball.carrier !== p) return;
    const hoop = this.attackHoop(p.team);
    const d = dist(p.pos, hoop);
    const isDunk = d < 100;
    const opponents = this.players.filter((q) => q.team !== p.team);

    let contest = 0;
    opponents.forEach((q) => {
      const qd = dist(q.pos, p.pos);
      if (qd < 48) contest += 0.16;
      else if (qd < 78) contest += 0.08;
    });
    contest = Math.min(0.36, contest);

    let make = 0.95 - Math.max(0, d - 55) * 0.0022 + (p.stats.shoot - 60) * 0.0045 - contest;
    if (isDunk) make = Math.max(make, 0.82);
    if (isAI) make += (this.difficulty - 1) * 0.14;
    make = clamp(make, 0.07, 0.96);

    // block check at release
    let blocker = null;
    for (const q of opponents) {
      const qd = dist(q.pos, p.pos);
      if (qd > 70) continue;
      const activeBlock = q === this.active && q.blockWindow > 0 && Math.random() < 0.62;
      const aiBlock = q.team === 1 && Math.random() < 0.06 + Math.max(0, 1 - qd / 70) * 0.1;
      if (activeBlock || aiBlock) { blocker = q; break; }
    }
    if (blocker) {
      this.ball.carrier = null;
      this.ball.z = 24;
      this.ball.vz = 80;
      this.ball.vel = { x: rand(-120, 120), y: rand(-120, 120) };
      this.ball.pickupCd = 0.3;
      this.ball.flight = null;
      this.float('BLOK!', p.pos.x, p.pos.y - 50, '#FF4D5E', 24);
      this.sound('block');
      this.shake(6, 0.25);
      if (blocker.team === 0) this.blocks += 1;
      return;
    }

    const points = d > THREE_R ? 3 : 2;
    const success = Math.random() < make;
    const apex = isDunk ? 55 : clamp(d * 0.42, 70, 155);
    const dur = isDunk ? 0.5 : clamp(d / 320, 0.62, 1.05);
    this.ball.carrier = null;
    this.ball.flight = {
      type: 'shot', from: { x: p.pos.x, y: p.pos.y }, to: { x: hoop.x, y: hoop.y },
      team: p.team, shooter: p, success, points, isDunk, t: 0, dur, apex
    };
    this.ball.z = 22;
    this.possTeam = p.team;
    this.shotClock = Math.max(this.shotClock, 1.5);
    p.shootCd = 1.1;
    this.sound('pass');
    if (p.team === 0) this.shots += 1;
  }

  resolveShot(f) {
    const b = this.ball;
    b.flight = null;
    const shooter = f.shooter;
    if (f.success) {
      this.score[f.team] += f.points;
      if (f.team === 0) {
        this.makes += 1;
        this.scorers[shooter.name] = (this.scorers[shooter.name] || 0) + f.points;
        this.float(`+${f.points}`, TOP_HOOP.x + rand(-30, 30), (f.team === 0 ? TOP_HOOP.y : BOTTOM_HOOP.y) + 35, '#FFD166', 30);
        this.float(pick(MESSAGES.make), f.team === 0 ? 180 : 420, 380, '#FFFFFF', 24);
      }
      this.rimFlash = 1;
      this.flash = 0.55;
      this.shake(f.isDunk ? 10 : 5, f.isDunk ? 0.4 : 0.25);
      this.sound(f.isDunk ? 'dunk' : 'score');
      this.burst(f.team === 0 ? TOP_HOOP.x : BOTTOM_HOOP.x, f.team === 0 ? TOP_HOOP.y : BOTTOM_HOOP.y, f.isDunk ? 26 : 16);
      if (f.isDunk) this.float(pick(MESSAGES.dunk), f.team === 0 ? 260 : 340, f.team === 0 ? 170 : 730, '#FF6B1A', 30);
      b.dead = true;
      b.pos = { x: f.to.x, y: f.to.y };
      b.z = 0;
      this.freeze = 1.15;
      this.pendingPossession = 1 - f.team;
      this.message(f.team === 0 ? 'BASKET KAMU! 🏀' : 'LAWAN MENCETAK!', 1.1);
    } else {
      b.pos = { x: f.to.x + rand(-14, 14), y: f.to.y };
      b.z = 16;
      b.vz = 40;
      b.vel = { x: rand(-150, 150), y: f.team === 0 ? rand(60, 160) : rand(-160, -60) };
      b.pickupCd = 0.3;
      this.rimFlash = 1;
      this.sound('rim');
      this.shake(3, 0.18);
      if (f.team === 0) this.float(pick(MESSAGES.miss), f.to.x, f.to.y + 40, '#FFD166', 18);
    }
  }

  resolveBlock(defender, f) {
    const b = this.ball;
    b.flight = null;
    b.carrier = null;
    b.pos = { x: b.pos.x, y: b.pos.y };
    b.z = 26;
    b.vz = 70;
    b.vel = { x: rand(-130, 130), y: f.team === 0 ? rand(40, 130) : rand(-130, -40) };
    b.pickupCd = 0.3;
    this.float('BLOK!', b.pos.x, b.pos.y - 40, '#FF4D5E', 26);
    this.sound('block');
    this.shake(7, 0.3);
    if (defender.team === 0) this.blocks += 1;
  }

  attemptSteal(defender, carrier, isAI) {
    if (!carrier || this.ball.carrier !== carrier) return;
    defender.stealCd = isAI ? 1.6 : 1.25;
    let chance = 0.2 + (defender.stats.defense - carrier.stats.dribble) * 0.006;
    if (!isAI) chance += 0.14;
    chance = clamp(chance, 0.08, 0.62);
    if (Math.random() < chance) {
      this.ball.carrier = defender;
      this.ball.flight = null;
      this.ball.z = 0; this.ball.vz = 0;
      this.ball.vel = { x: 0, y: 0 };
      this.possTeam = defender.team;
      this.shotClock = 14;
      defender.dribble = 0;
      this.float(pick(MESSAGES.steal), defender.pos.x, defender.pos.y - 50, '#5CFFB0', 24);
      this.sound('steal');
      this.shake(4, 0.2);
      if (defender.team === 0) { this.setActive(defender); this.steals += 1; }
      carrier.stun = 0.35;
    } else {
      defender.stun = 0.3;
      this.sound('pop');
      if (!isAI) this.float('HAMPIR!', defender.pos.x, defender.pos.y - 45, '#FFD166', 18);
    }
  }

  endMatch() {
    this.state = 'ended';
    this.endTimer = 1.7;
    this.sound('buzzer');
    this.message(this.score[0] > this.score[1] ? 'MENANG! 🏆' : (this.score[0] < this.score[1] ? 'COBA LAGI!' : 'SERI!'), 1.6);
  }

  report() {
    const win = this.score[0] > this.score[1];
    const draw = this.score[0] === this.score[1];
    let topName = null; let topPts = 0;
    Object.entries(this.scorers).forEach(([n, p]) => { if (p > topPts) { topPts = p; topName = n; } });
    this.onEnd({
      win, draw,
      score: this.score[0], oppScore: this.score[1],
      shots: this.shots, makes: this.makes, steals: this.steals, blocks: this.blocks,
      topScorer: topName, topPoints: topPts,
      overtime: this.overtime
    });
  }

  pause() {
    if (this.state === 'live') { this.prevState = this.state; this.state = 'paused'; }
  }

  resume() {
    if (this.state === 'paused') { this.state = this.prevState || 'live'; this.last = performance.now(); }
  }

  quit() {
    this.destroy();
  }

  /* ---------------- effects ---------------- */

  sound(name) { if (this.audio) this.audio.play(name); }

  message(text, t = 1) { this.messageData = { text, t, max: t }; }

  float(text, x, y, color = '#FFFFFF', size = 22) {
    this.floaters.push({ text, x, y, color, size, life: 1.1, max: 1.1, vy: -38 });
  }

  burst(x, y, n = 16) {
    for (let i = 0; i < n; i++) {
      const a = Math.random() * Math.PI * 2;
      const sp = rand(40, 190);
      this.particles.push({
        x, y, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp,
        life: rand(0.4, 1), max: 1, size: rand(2, 6),
        color: pick(['#FFD166', '#FF6B1A', '#FFFFFF', '#5CC8FF'])
      });
    }
  }

  shake(mag, time) { this.shakeMag = mag; this.shakeTime = time; }

  updateParticles(dt) {
    this.particles.forEach((p) => {
      p.x += p.vx * dt; p.y += p.vy * dt;
      p.vx *= 0.97; p.vy *= 0.97;
      p.life -= dt;
    });
    this.particles = this.particles.filter((p) => p.life > 0);
    this.floaters.forEach((f) => { f.y += f.vy * dt; f.vy *= 0.96; f.life -= dt; });
    this.floaters = this.floaters.filter((f) => f.life > 0);
  }

  /* ---------------- input ---------------- */

  pointerDown(e) {
    this._pt = { x: e.clientX, y: e.clientY, t: performance.now() };
  }

  pointerUp(e) {
    if (!this._pt) return;
    const dx = e.clientX - this._pt.x;
    const dy = e.clientY - this._pt.y;
    const dt = performance.now() - this._pt.t;
    this._pt = null;
    if (dt > 700) return;
    if (Math.hypot(dx, dy) > 34) {
      if (Math.abs(dy) > Math.abs(dx)) {
        if (dy < 0) this.swipe('up');
        else this.swipe('down');
      } else {
        this.swipe(dx < 0 ? 'left' : 'right');
      }
    } else if (this.state === 'live') {
      this.tapAt(e.clientX, e.clientY);
    }
  }

  tapAt(clientX, clientY) {
    if (this.ball.carrier && this.ball.carrier.team === 0) return;
    const rect = this.canvas.getBoundingClientRect();
    const x = (clientX - rect.left - this.ox) / this.scale;
    const y = (clientY - rect.top - this.oy) / this.scale;
    const mates = this.players.filter((p) => p.team === 0);
    let best = null; let bd = 55;
    mates.forEach((p) => { const d = Math.hypot(p.pos.x - x, p.pos.y - y); if (d < bd) { bd = d; best = p; } });
    if (best && best !== this.active) { this.setActive(best); this.sound('click'); }
  }

  /* ---------------- rendering ---------------- */

  resize() {
    const parent = this.canvas.parentElement;
    if (!parent) return;
    const rect = parent.getBoundingClientRect();
    this.cw = Math.max(1, Math.round(rect.width));
    this.ch = Math.max(1, Math.round(rect.height));
    this.dpr = Math.min(2, window.devicePixelRatio || 1);
    this.canvas.width = Math.round(this.cw * this.dpr);
    this.canvas.height = Math.round(this.ch * this.dpr);
    this.canvas.style.width = `${this.cw}px`;
    this.canvas.style.height = `${this.ch}px`;
  }

  computeCamera() {
    const availH = Math.max(240, this.ch - PAD_TOP - PAD_BOTTOM);
    this.scale = Math.min(this.cw / W, availH / 620);
    this.viewH = availH / this.scale;
    if (this.viewH >= H) {
      this.camY = (H - this.viewH) / 2;
    } else {
      const focus = this.ball.carrier ? this.ball.carrier.pos.y : this.ball.pos.y;
      const target = clamp(focus - this.viewH / 2, 0, H - this.viewH);
      this.camY += (target - this.camY) * 0.12;
    }
    this.ox = (this.cw - W * this.scale) / 2;
    this.oy = PAD_TOP - this.camY * this.scale;
  }

  render() {
    const ctx = this.ctx;
    if (!ctx || !this.cw) return;
    this.computeCamera();
    ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    ctx.clearRect(0, 0, this.cw, this.ch);

    let sx = 0; let sy = 0;
    if (this.shakeTime > 0) {
      const m = this.shakeMag * (this.shakeTime / 0.4);
      sx = rand(-m, m); sy = rand(-m, m);
    }

    ctx.save();
    ctx.translate(this.ox + sx, this.oy + sy);
    ctx.scale(this.scale, this.scale);

    const vx0 = -this.ox / this.scale;
    const vx1 = (this.cw - this.ox) / this.scale;
    const vy0 = this.camY;
    const vy1 = this.camY + this.viewH;

    this.drawBackground(ctx, vx0, vx1, vy0, vy1);
    this.drawCourt(ctx);
    this.drawHoop(ctx, TOP_HOOP, 'top');
    this.drawHoop(ctx, BOTTOM_HOOP, 'bottom');

    const sorted = this.players.slice().sort((a, b) => a.pos.y - b.pos.y);
    sorted.forEach((p) => this.drawPlayer(ctx, p));

    this.drawBall(ctx);

    this.particles.forEach((p) => {
      ctx.globalAlpha = clamp(p.life / p.max, 0, 1);
      ctx.fillStyle = p.color;
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
      ctx.fill();
    });
    ctx.globalAlpha = 1;

    this.floaters.forEach((f) => {
      const a = clamp(f.life / f.max, 0, 1);
      ctx.globalAlpha = a;
      ctx.font = `900 ${f.size}px "Trebuchet MS", system-ui, sans-serif`;
      ctx.textAlign = 'center';
      ctx.lineWidth = 5;
      ctx.strokeStyle = 'rgba(8,17,31,0.9)';
      ctx.strokeText(f.text, f.x, f.y);
      ctx.fillStyle = f.color;
      ctx.fillText(f.text, f.x, f.y);
    });
    ctx.globalAlpha = 1;
    ctx.restore();

    // screen-space effects
    if (this.flash > 0) {
      ctx.fillStyle = `rgba(255,255,255,${this.flash * 0.35})`;
      ctx.fillRect(0, 0, this.cw, this.ch);
    }

    if (this.state === 'intro') {
      const n = this.intro > 2.15 ? '3' : this.intro > 1.15 ? '2' : this.intro > 0.15 ? '1' : 'MULAI!';
      const frac = 1 - (this.intro % 1);
      const scale = n === 'MULAI!' ? 1 : 1.2 + Math.sin(frac * Math.PI) * 0.25;
      this.drawBigText(ctx, n, this.cw / 2, this.ch * 0.44, n === 'MULAI!' ? 46 : 92, scale, '#FFD166');
    }

    if (this.messageData) {
      const m = this.messageData;
      const a = clamp(m.t / 0.3, 0, 1) * clamp((m.max - m.t) / 0.15, 0, 1);
      ctx.globalAlpha = a;
      this.drawBigText(ctx, m.text, this.cw / 2, this.ch * 0.34, 30, 1, '#FFFFFF');
      ctx.globalAlpha = 1;
    }
  }

  drawBigText(ctx, text, x, y, size, scale = 1, color = '#FFF') {
    ctx.save();
    ctx.translate(x, y);
    ctx.scale(scale, scale);
    ctx.font = `900 ${size}px "Trebuchet MS", system-ui, sans-serif`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.lineWidth = Math.max(5, size * 0.12);
    ctx.strokeStyle = '#0E1B33';
    ctx.lineJoin = 'round';
    ctx.strokeText(text, 0, 0);
    ctx.fillStyle = color;
    ctx.fillText(text, 0, 0);
    ctx.restore();
  }

  drawBackground(ctx, x0, x1, y0, y1) {
    const t = this.court;
    const g = ctx.createLinearGradient(0, y0, 0, y1);
    if (t.style === 'arena') {
      g.addColorStop(0, '#050C18');
      g.addColorStop(0.5, '#0B1830');
      g.addColorStop(1, '#050C18');
    } else {
      g.addColorStop(0, t.bg);
      g.addColorStop(1, '#4F9A6A');
    }
    ctx.fillStyle = g;
    ctx.fillRect(x0, y0, x1 - x0, y1 - y0);

    if (t.style === 'arena') {
      // stands + crowd behind both baselines
      this.drawStands(ctx, y0, 0, 1);
      this.drawStands(ctx, H, y1, -1);
      // spotlights
      for (let i = 0; i < 4; i++) {
        const lx = 80 + i * 150;
        const rg = ctx.createRadialGradient(lx, 20, 10, lx, 20, 260);
        rg.addColorStop(0, 'rgba(255,240,190,0.18)');
        rg.addColorStop(1, 'rgba(255,240,190,0)');
        ctx.fillStyle = rg;
        ctx.beginPath(); ctx.arc(lx, 20, 260, 0, Math.PI * 2); ctx.fill();
      }
    } else {
      // grass texture + trees
      ctx.globalAlpha = 0.35;
      for (let i = 0; i < 70; i++) {
        const x = x0 + ((i * 137.5) % Math.max(1, x1 - x0));
        const y = y0 + ((i * 89.3) % Math.max(1, y1 - y0));
        ctx.fillStyle = i % 2 ? '#7CC98F' : '#3E8F5C';
        ctx.beginPath(); ctx.arc(x, y, 3 + (i % 4), 0, Math.PI * 2); ctx.fill();
      }
      ctx.globalAlpha = 1;
      this.drawTrees(ctx, x0, x1, y0, y1);
    }
  }

  drawStands(ctx, y, edge, dir) {
    const bandH = 210;
    const top = dir === 1 ? y - bandH : edge;
    ctx.fillStyle = '#111E36';
    ctx.fillRect(-200, top, W + 400, bandH);
    ctx.fillStyle = '#1A2C4C';
    for (let r = 0; r < 6; r++) {
      ctx.fillRect(-200, top + r * 34, W + 400, 18);
    }
    const colors = this.court.crowd;
    for (let r = 0; r < 6; r++) {
      for (let i = 0; i < 34; i++) {
        const x = -180 + i * 28 + (r % 2) * 14;
        const yy = top + r * 34 + 9;
        ctx.fillStyle = colors[(i + r) % colors.length];
        ctx.globalAlpha = 0.7;
        ctx.beginPath(); ctx.arc(x, yy, 5, 0, Math.PI * 2); ctx.fill();
      }
    }
    ctx.globalAlpha = 1;
    // railing
    ctx.fillStyle = '#FF6B1A';
    ctx.fillRect(-200, dir === 1 ? y - 8 : y + bandH - 4, W + 400, 6);
  }

  drawTrees(ctx, x0, x1, y0, y1) {
    const spots = [
      [-60, -40], [-130, 120], [-70, 300], [660, -20], [710, 160], [650, 330],
      [-40, 960], [120, 990], [470, 980], [680, 950], [-120, 760], [710, 700]
    ];
    spots.forEach(([x, y], i) => {
      if (x < x0 - 100 || x > x1 + 100 || y < y0 - 100 || y > y1 + 100) return;
      ctx.fillStyle = 'rgba(20,50,30,0.25)';
      ctx.beginPath(); ctx.ellipse(x + 8, y + 12, 34, 14, 0, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = '#2F7A4B';
      ctx.beginPath(); ctx.arc(x, y, 30, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = '#46A566';
      ctx.beginPath(); ctx.arc(x - 9, y - 8, 19, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = '#63C27F';
      ctx.beginPath(); ctx.arc(x - 13, y - 13, 9, 0, Math.PI * 2); ctx.fill();
    });
    // fence
    ctx.strokeStyle = 'rgba(255,255,255,0.18)';
    ctx.lineWidth = 2;
    for (let x = -40; x < W + 40; x += 34) {
      ctx.beginPath(); ctx.moveTo(x, H + 2); ctx.lineTo(x + 30, H + 120); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(x + 30, H + 2); ctx.lineTo(x, H + 120); ctx.stroke();
    }
  }

  drawCourt(ctx) {
    const t = this.court;
    ctx.save();
    ctx.shadowColor = 'rgba(0,0,0,0.35)';
    ctx.shadowBlur = 24;
    ctx.shadowOffsetY = 10;
    ctx.fillStyle = t.floor;
    ctx.fillRect(0, 0, W, H);
    ctx.restore();

    // planks / texture
    if (t.style === 'park') {
      ctx.fillStyle = 'rgba(255,255,255,0.035)';
      for (let i = 0; i < 260; i++) {
        const x = (i * 73.7) % W; const y = (i * 131.3) % H;
        ctx.fillRect(x, y, 3, 3);
      }
    } else {
      for (let y = 0; y < H; y += 34) {
        ctx.fillStyle = (y / 34) % 2 === 0 ? 'rgba(255,255,255,0.055)' : 'rgba(0,0,0,0.035)';
        ctx.fillRect(0, y, W, 34);
        ctx.strokeStyle = 'rgba(80,40,10,0.14)';
        ctx.lineWidth = 1;
        ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(W, y); ctx.stroke();
      }
      for (let i = 0; i < 40; i++) {
        const y = (i * 47.3) % H;
        ctx.strokeStyle = 'rgba(90,50,20,0.1)';
        ctx.beginPath(); ctx.moveTo(0, y); ctx.bezierCurveTo(180, y + 6, 400, y - 5, W, y + 2); ctx.stroke();
      }
    }

    // paint areas
    ctx.fillStyle = t.floor2;
    ctx.globalAlpha = 0.55;
    ctx.fillRect(205, 0, 190, 196);
    ctx.fillRect(205, H - 196, 190, 196);
    ctx.globalAlpha = 1;

    const lw = 5;
    ctx.strokeStyle = t.line;
    ctx.lineWidth = lw;
    ctx.lineJoin = 'round';

    // boundary
    ctx.strokeRect(10, 10, W - 20, H - 20);

    // half court
    ctx.beginPath(); ctx.moveTo(10, 450); ctx.lineTo(W - 10, 450); ctx.stroke();
    ctx.beginPath(); ctx.arc(300, 450, 68, 0, Math.PI * 2); ctx.stroke();
    ctx.beginPath(); ctx.arc(300, 450, 24, 0, Math.PI * 2); ctx.stroke();

    // keys
    ctx.strokeRect(205, 10, 190, 186);
    ctx.strokeRect(205, H - 196, 190, 186);
    ctx.beginPath(); ctx.arc(300, 196, 58, 0, Math.PI * 2); ctx.stroke();
    ctx.beginPath(); ctx.arc(300, H - 196, 58, 0, Math.PI * 2); ctx.stroke();

    // three point arcs
    ctx.beginPath(); ctx.arc(300, 92, THREE_R, 0, Math.PI); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(75, 92); ctx.lineTo(75, 10); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(525, 92); ctx.lineTo(525, 10); ctx.stroke();

    ctx.beginPath(); ctx.arc(300, H - 92, THREE_R, Math.PI, Math.PI * 2); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(75, H - 92); ctx.lineTo(75, H - 10); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(525, H - 92); ctx.lineTo(525, H - 10); ctx.stroke();

    // restricted arcs
    ctx.lineWidth = 3;
    ctx.beginPath(); ctx.arc(300, 92, 46, 0.15, Math.PI - 0.15); ctx.stroke();
    ctx.beginPath(); ctx.arc(300, H - 92, 46, Math.PI + 0.15, Math.PI * 2 - 0.15); ctx.stroke();

    // center logo
    ctx.save();
    ctx.translate(300, 450);
    ctx.fillStyle = 'rgba(14,27,51,0.1)';
    ctx.beginPath(); ctx.arc(0, 0, 58, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = 'rgba(14,27,51,0.32)';
    ctx.font = '900 36px "Trebuchet MS", system-ui, sans-serif';
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.fillText('ADA', 0, -6);
    ctx.font = '800 9px "Trebuchet MS", system-ui, sans-serif';
    ctx.letterSpacing = '2px';
    ctx.fillText('SUPER LEAGUE', 0, 22);
    ctx.restore();

    // court name
    ctx.fillStyle = 'rgba(255,255,255,0.35)';
    ctx.font = '800 10px "Trebuchet MS", system-ui, sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText(this.court.name.toUpperCase(), 300, H - 22);
  }

  drawHoop(ctx, hoop, side) {
    const dir = side === 'top' ? 1 : -1;
    const boardY = hoop.y - 36 * dir;
    ctx.save();
    // support
    ctx.fillStyle = '#1B2B45';
    ctx.fillRect(hoop.x - 4, side === 'top' ? 22 : H - 34, 8, 24);
    // backboard
    ctx.fillStyle = '#F7FBFF';
    ctx.strokeStyle = '#0E1B33';
    ctx.lineWidth = 3;
    ctx.fillRect(hoop.x - 52, boardY - 5, 104, 10);
    ctx.strokeRect(hoop.x - 52, boardY - 5, 104, 10);
    ctx.fillStyle = '#FF6B1A';
    ctx.fillRect(hoop.x - 20, boardY - 2, 40, 4);
    // rim
    ctx.strokeStyle = '#FF5200';
    ctx.lineWidth = 5;
    ctx.beginPath();
    ctx.ellipse(hoop.x, hoop.y, RIM_R, 8, 0, 0, Math.PI * 2);
    ctx.stroke();
    // net
    const wob = this.rimFlash > 0 ? Math.sin(this.elapsed * 40) * 3 * this.rimFlash : 0;
    const netBottom = hoop.y + 34 * dir;
    ctx.strokeStyle = 'rgba(255,255,255,0.9)';
    ctx.lineWidth = 1.6;
    for (let i = -2; i <= 2; i++) {
      const x = hoop.x + i * 8;
      ctx.beginPath();
      ctx.moveTo(hoop.x + i * 10, hoop.y + 2 * dir);
      ctx.lineTo(hoop.x + i * 5 + wob, netBottom);
      ctx.stroke();
    }
    for (let r = 1; r <= 2; r++) {
      ctx.beginPath();
      ctx.ellipse(hoop.x + wob * (r / 3), hoop.y + 12 * r * dir, RIM_R - r * 5, 3, 0, 0, Math.PI * 2);
      ctx.stroke();
    }
    ctx.restore();
  }

  drawPlayer(ctx, p) {
    const team0 = p.team === 0;
    const kit = team0 ? this.jersey : { primary: this.opp.color, secondary: '#0E1B33', accent: this.opp.color2 };
    const active = p === this.active && p.team === 0;
    const jump = p.jump > 0 ? Math.sin((1 - p.jump / 0.42) * Math.PI) * 22 : 0;
    const run = Math.sin(p.anim * 2) * (p.moving ? 3 : 0.5);
    const bob = p.moving ? Math.abs(Math.sin(p.anim * 2)) * 2.5 : Math.sin(this.elapsed * 2 + p.idx) * 1.2;

    ctx.save();
    ctx.translate(p.pos.x, p.pos.y);

    // shadow
    ctx.fillStyle = 'rgba(0,0,0,0.22)';
    ctx.beginPath();
    ctx.ellipse(0, 18, 20, 8, 0, 0, Math.PI * 2);
    ctx.fill();

    if (active) {
      const pulse = 1 + Math.sin(this.elapsed * 5) * 0.06;
      ctx.save();
      ctx.scale(pulse, pulse);
      ctx.strokeStyle = 'rgba(255,107,26,0.95)';
      ctx.lineWidth = 3.5;
      ctx.setLineDash([9, 7]);
      ctx.lineDashOffset = -this.elapsed * 26;
      ctx.beginPath();
      ctx.ellipse(0, 16, 27, 13, 0, 0, Math.PI * 2);
      ctx.stroke();
      ctx.restore();
      // arrow
      ctx.fillStyle = '#FF6B1A';
      ctx.beginPath();
      ctx.moveTo(0, -56 - bob + Math.sin(this.elapsed * 5) * 2);
      ctx.lineTo(-8, -66 - bob);
      ctx.lineTo(8, -66 - bob);
      ctx.closePath();
      ctx.fill();
      ctx.strokeStyle = '#0E1B33';
      ctx.lineWidth = 2;
      ctx.stroke();
    }

    ctx.translate(0, -jump - bob);

    // legs
    ctx.fillStyle = '#1B2B45';
    roundRect(ctx, -12, 8, 9, 18 + run, 4); ctx.fill();
    roundRect(ctx, 3, 8, 9, 18 - run, 4); ctx.fill();
    // shoes
    ctx.fillStyle = kit.accent;
    roundRect(ctx, -14, 24 + run, 13, 7, 3); ctx.fill();
    roundRect(ctx, 1, 24 - run, 13, 7, 3); ctx.fill();

    // body / jersey
    ctx.fillStyle = kit.primary;
    ctx.strokeStyle = '#0E1B33';
    ctx.lineWidth = 2.2;
    roundRect(ctx, -16, -14, 32, 29, 9);
    ctx.fill(); ctx.stroke();

    // jersey side trim
    ctx.fillStyle = kit.secondary;
    roundRect(ctx, -16, 6, 32, 9, 4); ctx.fill();
    ctx.fillStyle = kit.accent;
    ctx.fillRect(-15, 8, 30, 2);

    // arms
    const armY = jump > 2 ? -20 : -2;
    ctx.fillStyle = p.skin;
    ctx.strokeStyle = '#0E1B33';
    ctx.lineWidth = 2;
    ctx.beginPath(); ctx.arc(-19, armY, 5.5, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
    ctx.beginPath(); ctx.arc(19, armY, 5.5, 0, Math.PI * 2); ctx.fill(); ctx.stroke();

    // number
    ctx.fillStyle = kit.accent;
    ctx.font = '900 12px "Trebuchet MS", system-ui, sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(String(p.number), 0, -2);

    // head
    ctx.fillStyle = p.skin;
    ctx.strokeStyle = '#0E1B33';
    ctx.lineWidth = 2.2;
    ctx.beginPath(); ctx.arc(0, -27, 13, 0, Math.PI * 2); ctx.fill(); ctx.stroke();

    // hair
    ctx.fillStyle = p.hair;
    ctx.beginPath();
    if (p.hairStyle === 'bun' || p.hairStyle === 'pony') {
      ctx.arc(0, -30, 13.5, Math.PI * 1.02, Math.PI * 1.98);
      ctx.fill();
      ctx.beginPath(); ctx.arc(0, -40, 5, 0, Math.PI * 2); ctx.fill();
    } else if (p.hairStyle === 'curly') {
      ctx.arc(0, -31, 14, Math.PI, Math.PI * 2);
      ctx.fill();
      for (let i = -2; i <= 2; i++) { ctx.beginPath(); ctx.arc(i * 5, -41, 4.5, 0, Math.PI * 2); ctx.fill(); }
    } else {
      ctx.arc(0, -30, 13.5, Math.PI * 1.02, Math.PI * 1.98);
      ctx.fill();
      if (p.hairStyle === 'spiky') {
        ctx.beginPath();
        ctx.moveTo(-12, -34); ctx.lineTo(-7, -45); ctx.lineTo(-2, -35);
        ctx.lineTo(3, -46); ctx.lineTo(8, -35); ctx.lineTo(13, -42); ctx.lineTo(12, -30);
        ctx.closePath(); ctx.fill();
      }
    }

    // eyes + smile
    ctx.fillStyle = '#0E1B33';
    ctx.beginPath(); ctx.arc(-4.5, -27, 1.5, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(4.5, -27, 1.5, 0, Math.PI * 2); ctx.fill();
    ctx.strokeStyle = '#0E1B33';
    ctx.lineWidth = 1.4;
    ctx.beginPath(); ctx.arc(0, -23, 4, 0.2, Math.PI - 0.2); ctx.stroke();

    // headband for player team
    if (team0) {
      ctx.strokeStyle = kit.secondary;
      ctx.lineWidth = 3;
      ctx.beginPath(); ctx.arc(0, -30, 12.5, Math.PI * 1.06, Math.PI * 1.94); ctx.stroke();
    }

    ctx.restore();
  }

  drawBall(ctx) {
    const b = this.ball;
    if (b.dead) return;
    const x = b.pos.x;
    const y = b.pos.y - b.z - 4;
    const shadowScale = clamp(1 - b.z / 220, 0.35, 1);

    ctx.fillStyle = `rgba(0,0,0,${0.2 * shadowScale})`;
    ctx.beginPath();
    ctx.ellipse(b.pos.x, b.pos.y + 12, 10 * shadowScale, 4 * shadowScale, 0, 0, Math.PI * 2);
    ctx.fill();

    // trail for shots
    if (b.flight?.type === 'shot') {
      ctx.fillStyle = 'rgba(255,107,26,0.18)';
      for (let i = 1; i <= 4; i++) {
        const tt = clamp(b.flight.t - i * 0.045, 0, 1);
        const px = b.flight.from.x + (b.flight.to.x - b.flight.from.x) * tt;
        const py = b.flight.from.y + (b.flight.to.y - b.flight.from.y) * tt - Math.sin(Math.PI * tt) * b.flight.apex;
        ctx.beginPath(); ctx.arc(px, py, 8 - i, 0, Math.PI * 2); ctx.fill();
      }
    }

    ctx.save();
    ctx.translate(x, y);
    ctx.fillStyle = '#FF7A1A';
    ctx.strokeStyle = '#14264A';
    ctx.lineWidth = 2;
    ctx.beginPath(); ctx.arc(0, 0, 11, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
    ctx.strokeStyle = '#14264A';
    ctx.lineWidth = 1.6;
    ctx.beginPath(); ctx.arc(0, 0, 11, -Math.PI / 2, Math.PI / 2); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(-11, 0); ctx.lineTo(11, 0); ctx.stroke();
    ctx.beginPath(); ctx.arc(0, 0, 11, Math.PI * 0.15, Math.PI * 0.85); ctx.stroke();
    ctx.beginPath(); ctx.arc(0, 0, 11, Math.PI * 1.15, Math.PI * 1.85); ctx.stroke();
    ctx.restore();
  }
}

/* =========================================================
   ADA Super League - Basketball
   Bright cartoon mobile UI. Orange + navy.
   ========================================================= */

:root {
  --navy: #0E1B33;
  --navy-2: #16294A;
  --navy-3: #22395F;
  --orange: #FF6B1A;
  --orange-2: #FF9A3C;
  --orange-3: #FFB35C;
  --gold: #FFC93C;
  --gold-2: #FFE082;
  --cream: #FFF6E8;
  --cream-2: #FFE9CC;
  --paper: #FFFFFF;
  --sky: #5CC8FF;
  --green: #2ED3A6;
  --red: #FF4D5E;
  --muted: #6B7A93;
  --shadow: 0 5px 0 rgba(14, 27, 51, 0.9);
  --shadow-soft: 0 4px 0 rgba(14, 27, 51, 0.14);
  --safe-b: env(safe-area-inset-bottom, 0px);
  --safe-t: env(safe-area-inset-top, 0px);
}

* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }

html, body {
  margin: 0;
  height: 100%;
  overflow: hidden;
  background: #060D1A;
  font-family: "Trebuchet MS", "Arial Rounded MT Bold", "Segoe UI", system-ui, -apple-system, sans-serif;
  color: var(--navy);
  -webkit-font-smoothing: antialiased;
  overscroll-behavior: none;
}

body {
  display: flex;
  justify-content: center;
  align-items: stretch;
  background:
    radial-gradient(900px 500px at 50% -10%, #1C3A66 0%, transparent 60%),
    radial-gradient(700px 500px at 0% 100%, #2A1A0C 0%, transparent 55%),
    #060D1A;
}

button, input, select { font-family: inherit; }
button { cursor: pointer; user-select: none; }
button:focus-visible, input:focus-visible, select:focus-visible { outline: 3px solid var(--sky); outline-offset: 2px; }
img, svg { display: block; }
.hidden { display: none !important; }
.center { text-align: center; }

#app {
  position: relative;
  width: 100%;
  max-width: 480px;
  height: 100dvh;
  overflow: hidden;
  background: var(--cream);
  box-shadow: 0 0 60px rgba(0, 0, 0, 0.65);
}

@media (min-width: 481px) {
  #app { border-left: 1px solid rgba(255,255,255,.08); border-right: 1px solid rgba(255,255,255,.08); }
}

/* ---------------- screens ---------------- */
.screen {
  position: absolute;
  inset: 0;
  display: none;
  flex-direction: column;
  overflow: hidden;
  background: var(--cream);
}
.screen.active { display: flex; }

.scroll-body {
  flex: 1;
  overflow-y: auto;
  overflow-x: hidden;
  padding: 4px 16px calc(104px + var(--safe-b));
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}
.scroll-body::-webkit-scrollbar { display: none; }

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: calc(14px + var(--safe-t)) 18px 8px;
  background: var(--cream);
}
.eyebrow {
  margin: 0 0 2px;
  font-size: 9px;
  letter-spacing: 0.16em;
  font-weight: 900;
  color: var(--orange);
}
.page-title {
  margin: 0;
  font-size: 30px;
  line-height: 1;
  font-weight: 900;
  letter-spacing: -0.02em;
  color: var(--navy);
}
.section-title {
  margin: 20px 2px 10px;
  font-size: 17px;
  font-weight: 900;
  letter-spacing: -0.01em;
}
.tiny { font-size: 10.5px; line-height: 1.45; color: var(--muted); margin: 10px 2px; }
.tiny b { color: var(--navy); }
.muted { color: var(--muted); }

.card {
  background: var(--paper);
  border: 2.5px solid var(--navy);
  border-radius: 20px;
  box-shadow: var(--shadow-soft);
  padding: 14px;
}

.coin-chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  background: var(--navy);
  color: var(--gold);
  border: 2.5px solid var(--navy);
  border-radius: 999px;
  padding: 7px 12px;
  font-size: 14px;
  box-shadow: 0 3px 0 rgba(14,27,51,.25);
  white-space: nowrap;
}
.coin-chip span { font-size: 14px; }
.coin-chip b { color: #fff; font-size: 14px; }

/* ---------------- logo ---------------- */
.logo { display: flex; align-items: center; gap: 10px; }
.ball-icon { width: 54px; height: 54px; flex: none; filter: drop-shadow(0 4px 0 rgba(0,0,0,.25)); }
.logo-text { display: flex; flex-direction: column; line-height: .92; }
.logo-ada {
  font-size: 36px;
  font-weight: 900;
  letter-spacing: -0.03em;
  color: var(--orange);
  -webkit-text-stroke: 2px var(--navy);
  paint-order: stroke fill;
  text-shadow: 0 3px 0 rgba(14, 27, 51, 0.35);
}
.logo-academy {
  font-size: 8.5px;
  font-weight: 900;
  letter-spacing: 0.13em;
  color: #fff;
  margin-top: 3px;
}
.logo-league {
  align-self: flex-start;
  margin-top: 5px;
  background: var(--gold);
  color: var(--navy);
  border: 1.5px solid var(--navy);
  border-radius: 4px;
  padding: 2px 6px 1px;
  font-size: 8px;
  font-weight: 900;
  letter-spacing: 0.14em;
}
.logo--hero { gap: 12px; justify-content: center; }
.logo--hero .ball-icon { width: 76px; height: 76px; }
.logo--hero .logo-ada { font-size: 52px; }
.logo--hero .logo-academy { font-size: 11px; letter-spacing: 0.15em; }
.logo--hero .logo-league { font-size: 10px; padding: 3px 8px; }
.logo--sm .ball-icon { width: 40px; height: 40px; }
.logo--sm .logo-ada { font-size: 27px; -webkit-text-stroke-width: 1.5px; }
.logo--sm .logo-academy { font-size: 6.6px; letter-spacing: .11em; }
.logo--sm .logo-league { display: none; }

/* ---------------- buttons ---------------- */
.btn {
  appearance: none;
  border: 2.5px solid var(--navy);
  border-radius: 14px;
  background: var(--cream);
  color: var(--navy);
  font-weight: 900;
  font-size: 14px;
  letter-spacing: 0.03em;
  padding: 11px 16px;
  box-shadow: 0 4px 0 var(--navy);
  transition: transform .07s ease, box-shadow .07s ease;
  text-transform: uppercase;
  line-height: 1.1;
}
.btn:active { transform: translateY(3px); box-shadow: 0 1px 0 var(--navy); }
.btn-primary {
  background: linear-gradient(180deg, var(--orange-2), var(--orange));
  color: #fff;
  text-shadow: 0 2px 0 rgba(14, 27, 51, 0.28);
}
.btn-gold { background: linear-gradient(180deg, var(--gold-2), var(--gold)); }
.btn-navy { background: var(--navy); color: #fff; }
.btn-green { background: linear-gradient(180deg, #55E4B8, #22BE8F); color: var(--navy); }
.btn-block { display: block; width: 100%; }
.btn-big { font-size: 18px; padding: 15px 18px; border-radius: 16px; }
.btn-sm { font-size: 11px; padding: 8px 11px; border-radius: 10px; box-shadow: 0 3px 0 var(--navy); }
.btn-ghost { background: transparent; box-shadow: none; border-color: transparent; color: var(--muted); }
.btn:disabled { opacity: .45; filter: grayscale(.4); }

.icon-btn {
  width: 40px; height: 40px;
  border-radius: 12px;
  border: 2.5px solid rgba(255,255,255,.25);
  background: rgba(255,255,255,.1);
  color: #fff;
  font-size: 18px;
  display: grid;
  place-items: center;
  flex: none;
}

/* ---------------- onboarding ---------------- */
#screen-onboard {
  background:
    radial-gradient(600px 380px at 50% 0%, #1E3E6E 0%, transparent 70%),
    radial-gradient(500px 300px at 100% 100%, #43240E 0%, transparent 65%),
    var(--navy);
  color: #fff;
}
.onboard-deco { position: absolute; inset: 0; pointer-events: none; overflow: hidden; }
.deco-ball { position: absolute; opacity: .16; filter: blur(.3px); }
.deco-ball.b1 { font-size: 150px; top: -40px; right: -40px; transform: rotate(-18deg); }
.deco-ball.b2 { font-size: 110px; bottom: 60px; left: -40px; transform: rotate(20deg); }
.deco-star { position: absolute; color: var(--gold); opacity: .55; font-size: 24px; animation: twinkle 2.4s ease-in-out infinite; }
.deco-star.s1 { top: 140px; left: 24px; }
.deco-star.s2 { top: 90px; right: 36px; font-size: 16px; animation-delay: 1.1s; }
.deco-arc {
  position: absolute;
  width: 460px; height: 460px;
  border: 2px dashed rgba(255,255,255,.12);
  border-radius: 50%;
  bottom: -220px; left: 50%;
  transform: translateX(-50%);
}
.onboard-scroll {
  position: relative;
  z-index: 2;
  height: 100%;
  overflow-y: auto;
  padding: calc(26px + var(--safe-t)) 18px calc(28px + var(--safe-b));
  scrollbar-width: none;
}
.onboard-scroll::-webkit-scrollbar { display: none; }
.onboard-tag {
  text-align: center;
  color: #D6E3F7;
  font-size: 12.5px;
  line-height: 1.5;
  margin: 12px 0 18px;
}
.onboard-tag b { color: var(--gold); }

.form-card {
  background: var(--cream);
  color: var(--navy);
  border: 3px solid var(--navy);
  border-radius: 24px;
  padding: 18px;
  box-shadow: 0 8px 0 rgba(0, 0, 0, .4), inset 0 2px 0 #fff;
}
.form-title { margin: 0 0 3px; font-size: 24px; font-weight: 900; letter-spacing: -0.02em; }
.form-sub { margin: 0 0 14px; font-size: 11.5px; line-height: 1.45; color: var(--muted); }
.field { display: flex; flex-direction: column; gap: 5px; margin-bottom: 11px; }
.field > span { font-size: 10px; font-weight: 900; letter-spacing: .1em; text-transform: uppercase; color: var(--navy-3); }
.field input, .field select {
  width: 100%;
  height: 46px;
  border: 2.5px solid var(--navy);
  border-radius: 12px;
  background: #fff;
  padding: 0 12px;
  font-size: 15px;
  font-weight: 700;
  color: var(--navy);
  box-shadow: inset 0 2px 0 rgba(14,27,51,.06);
}
.field input::placeholder { color: #A9B6C9; font-weight: 600; }
.field select { appearance: none; background-image: linear-gradient(45deg, transparent 50%, var(--navy) 50%), linear-gradient(135deg, var(--navy) 50%, transparent 50%); background-position: calc(100% - 18px) 20px, calc(100% - 13px) 20px; background-size: 5px 5px; background-repeat: no-repeat; }
.field-row { display: flex; gap: 10px; }
.field-row .field:first-child { width: 90px; flex: none; }
.field-grow { flex: 1; }
.input-prefix { display: flex; align-items: center; border: 2.5px solid var(--navy); border-radius: 12px; background: #fff; overflow: hidden; }
.input-prefix span { padding: 0 10px; font-weight: 900; font-size: 14px; color: var(--navy); background: var(--cream-2); align-self: stretch; display: flex; align-items: center; border-right: 2px solid var(--navy); }
.input-prefix input { border: 0; box-shadow: none; height: 42px; padding-left: 10px; }
.form-error { color: #D9253A; font-size: 11.5px; font-weight: 800; min-height: 0; margin: 0 0 8px; line-height: 1.3; }
.form-error:empty { display: none; }
.onboard-badges { display: flex; justify-content: center; gap: 8px; flex-wrap: wrap; margin-top: 16px; }
.onboard-badges span {
  font-size: 9.5px; font-weight: 900; color: #D6E3F7;
  background: rgba(255,255,255,.08); border: 1px solid rgba(255,255,255,.16);
  padding: 6px 9px; border-radius: 999px;
}

/* ---------------- home ---------------- */
#screen-home { background: var(--cream); }
.home-hero {
  position: relative;
  background:
    radial-gradient(380px 220px at 88% -20%, #2E4C7E 0%, transparent 70%),
    var(--navy);
  padding: calc(14px + var(--safe-t)) 16px 20px;
  border-bottom: 3px solid var(--navy);
  overflow: hidden;
  flex: none;
}
.home-hero::after {
  content: "";
  position: absolute;
  right: -70px; bottom: -130px;
  width: 260px; height: 260px;
  border: 2px dashed rgba(255,255,255,.12);
  border-radius: 50%;
  pointer-events: none;
}
.hero-top { display: flex; align-items: center; justify-content: space-between; gap: 10px; position: relative; z-index: 1; }
.profile-strip {
  position: relative;
  z-index: 1;
  margin-top: 14px;
  display: flex;
  align-items: center;
  gap: 10px;
  background: rgba(255,255,255,.08);
  border: 1.5px solid rgba(255,255,255,.16);
  border-radius: 16px;
  padding: 9px 10px;
}
.profile-strip .avatar { width: 44px; height: 44px; }
.profile-info { min-width: 0; flex: 1; }
.profile-name { color: #fff; font-weight: 900; font-size: 14px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.profile-meta { color: #B9CBE4; font-size: 9.5px; margin-top: 2px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.profile-meta b { color: var(--gold); }
.xp-track { height: 5px; border-radius: 3px; background: rgba(255,255,255,.16); margin-top: 5px; overflow: hidden; }
.xp-track i { display: block; height: 100%; background: linear-gradient(90deg, var(--gold), var(--orange-2)); border-radius: 3px; }
.home-body { padding-top: 14px; }

.daily-banner {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 10px;
  background: linear-gradient(120deg, #FFE082, var(--gold));
  border: 2.5px solid var(--navy);
  border-radius: 16px;
  padding: 10px 12px;
  box-shadow: var(--shadow-soft);
  text-align: left;
  color: var(--navy);
  margin-bottom: 12px;
  position: relative;
  overflow: hidden;
}
.daily-banner::after {
  content: "";
  position: absolute; top: 0; left: -60%;
  width: 40%; height: 100%;
  background: linear-gradient(90deg, transparent, rgba(255,255,255,.55), transparent);
  transform: skewX(-18deg);
  animation: shine 3.6s ease-in-out infinite;
}
.daily-banner .gift { font-size: 28px; animation: wiggle 2.2s ease-in-out infinite; }
.daily-banner .d-text { flex: 1; min-width: 0; }
.daily-banner .d-title { font-weight: 900; font-size: 12.5px; line-height: 1.1; }
.daily-banner .d-sub { font-size: 9.5px; margin-top: 2px; opacity: .8; font-weight: 700; }
.daily-banner .d-go { background: var(--navy); color: #fff; border-radius: 999px; font-size: 10px; font-weight: 900; padding: 7px 10px; white-space: nowrap; }
.daily-banner.claimed { background: #FFF1C9; opacity: .85; }
.daily-banner.claimed::after { display: none; }

.play-card {
  width: 100%;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  text-align: left;
  color: #fff;
  background: linear-gradient(135deg, #FF8A2B 0%, var(--orange) 55%, #F24E00 100%);
  border: 3px solid var(--navy);
  border-radius: 22px;
  padding: 15px 16px;
  box-shadow: 0 6px 0 var(--navy);
  overflow: hidden;
  margin-bottom: 14px;
}
.play-card::before {
  content: "";
  position: absolute; right: -36px; top: -50px;
  width: 190px; height: 190px;
  border: 16px solid rgba(255,255,255,.14);
  border-radius: 50%;
}
.play-card:active { transform: translateY(3px); box-shadow: 0 3px 0 var(--navy); }
.play-card .p-eyebrow { font-size: 9px; letter-spacing: .15em; font-weight: 900; opacity: .9; }
.play-card .p-title { font-size: 25px; font-weight: 900; line-height: 1.02; letter-spacing: -.02em; text-shadow: 0 2px 0 rgba(14,27,51,.25); margin: 3px 0 4px; }
.play-card .p-sub { font-size: 10.5px; font-weight: 800; opacity: .95; }
.play-card .p-sub b { color: var(--gold); }
.play-card .p-ball { font-size: 46px; flex: none; filter: drop-shadow(0 4px 0 rgba(14,27,51,.25)); transform: rotate(-12deg); animation: floaty 2.6s ease-in-out infinite; }
.play-card .p-arrow { flex: none; width: 34px; height: 34px; border-radius: 50%; background: rgba(255,255,255,.2); border: 2px solid rgba(255,255,255,.5); display: grid; place-items: center; font-weight: 900; font-size: 16px; }

.trial-banner {
  background: linear-gradient(120deg, #FFE082, #FFC93C);
  border: 2.5px solid var(--navy);
  border-radius: 16px;
  padding: 11px 12px;
  display: flex;
  gap: 10px;
  align-items: center;
  margin-bottom: 14px;
  box-shadow: var(--shadow-soft);
}
.trial-banner .t-emoji { font-size: 26px; }
.trial-banner .t-text { flex: 1; font-size: 10.5px; font-weight: 700; line-height: 1.3; }
.trial-banner .t-text b { display: block; font-size: 12.5px; font-weight: 900; }
.trial-banner button { border: 2px solid var(--navy); background: var(--navy); color: #fff; border-radius: 999px; padding: 7px 9px; font-size: 9px; font-weight: 900; }

.league-mini { margin-bottom: 12px; }
.lm-top { display: flex; align-items: center; gap: 10px; }
.lm-icon { width: 44px; height: 44px; border-radius: 13px; display: grid; place-items: center; font-size: 22px; border: 2px solid var(--navy); flex: none; }
.lm-name { font-size: 14px; font-weight: 900; line-height: 1.1; }
.lm-sub { font-size: 9.5px; color: var(--muted); font-weight: 700; margin-top: 2px; }
.lm-arrow { margin-left: auto; font-weight: 900; color: var(--orange); font-size: 18px; }
.lm-bar { display: flex; gap: 5px; margin-top: 10px; }
.lm-bar i { flex: 1; height: 8px; border-radius: 5px; background: #E9DFD0; border: 1.5px solid rgba(14,27,51,.1); }
.lm-bar i.on { background: linear-gradient(90deg, var(--gold), var(--orange)); border-color: var(--navy); }

.home-tip {
  border: 2px dashed rgba(14,27,51,.22);
  background: #FFFBF2;
  border-radius: 14px;
  padding: 10px 12px;
  font-size: 10.5px;
  line-height: 1.45;
  color: #56657E;
  margin-bottom: 4px;
}
.home-tip b { color: var(--navy); }

/* ---------------- league ---------------- */
#screen-league { background: var(--cream); }
.league-hero {
  border: 3px solid var(--navy);
  border-radius: 22px;
  padding: 16px;
  color: #fff;
  background: linear-gradient(135deg, var(--navy-2), var(--navy));
  box-shadow: 0 5px 0 var(--navy);
  position: relative;
  overflow: hidden;
  margin-top: 6px;
}
.league-hero::after {
  content: "";
  position: absolute; right: -40px; bottom: -60px;
  width: 180px; height: 180px;
  border: 14px solid rgba(255,255,255,.07);
  border-radius: 50%;
}
.lh-eyebrow { font-size: 9px; letter-spacing: .16em; font-weight: 900; color: var(--gold); }
.lh-name { font-size: 27px; font-weight: 900; line-height: 1; margin: 4px 0 6px; letter-spacing: -.02em; text-shadow: 0 3px 0 rgba(0,0,0,.25); }
.lh-sub { font-size: 10.5px; color: #C6D5E9; line-height: 1.4; }
.lh-row { display: flex; align-items: center; gap: 8px; margin-top: 12px; }
.lh-badge { background: var(--gold); color: var(--navy); border-radius: 8px; padding: 5px 8px; font-size: 10px; font-weight: 900; }
.lh-points { margin-left: auto; font-size: 12px; font-weight: 900; color: #fff; }
.lh-points b { font-size: 20px; color: var(--gold); }
.lh-icon { font-size: 38px; position: absolute; right: 14px; top: 12px; filter: drop-shadow(0 3px 0 rgba(0,0,0,.3)); }
#league-progress { margin-top: 12px; }
.progress-head { display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px; font-size: 11px; font-weight: 900; }
.progress-head span:last-child { color: var(--orange); }
.pips { display: flex; gap: 6px; }
.pips i { flex: 1; height: 12px; border-radius: 999px; border: 2px solid rgba(14,27,51,.15); background: #EDE3D5; }
.pips i.on { background: linear-gradient(90deg, var(--orange-2), var(--orange)); border-color: var(--navy); }
.opponent-list { display: flex; flex-direction: column; gap: 9px; }
.opponent-card {
  display: flex;
  align-items: center;
  gap: 10px;
  background: #fff;
  border: 2.5px solid var(--navy);
  border-radius: 16px;
  padding: 9px 10px;
  box-shadow: var(--shadow-soft);
}
.opponent-card.won { background: #ECFFF7; border-color: #168A63; }
.opponent-card.lost { background: #FFF1F1; }
.opponent-mascot {
  width: 48px; height: 48px; border-radius: 14px;
  display: grid; place-items: center;
  font-size: 25px;
  border: 2.5px solid var(--navy);
  flex: none;
  box-shadow: inset 0 -4px 0 rgba(0,0,0,.12);
}
.opponent-info { flex: 1; min-width: 0; }
.opponent-name { font-size: 13px; font-weight: 900; line-height: 1.1; }
.opponent-meta { font-size: 9px; color: var(--muted); margin-top: 2px; font-weight: 700; display: flex; gap: 6px; align-items: center; flex-wrap: wrap; }
.rating-pill { background: var(--cream-2); border-radius: 999px; padding: 2px 6px; font-weight: 900; color: var(--navy); font-size: 8.5px; }
.opponent-status { font-size: 9px; font-weight: 900; padding: 4px 7px; border-radius: 999px; }
.opponent-status.win { background: #C9F7E5; color: #0C7A55; }
.opponent-status.loss { background: #FFD9DD; color: #B0182B; }
.opponent-play { flex: none; }
.opponent-card.locked { opacity: .55; filter: grayscale(.5); }

.ladder { display: flex; flex-direction: column; gap: 7px; }
.ladder-row {
  display: flex;
  align-items: center;
  gap: 10px;
  background: #fff;
  border: 2px solid rgba(14,27,51,.16);
  border-radius: 14px;
  padding: 9px 11px;
  opacity: .68;
}
.ladder-row.current { opacity: 1; border: 2.5px solid var(--orange); background: #FFF6EC; box-shadow: 0 3px 0 rgba(255,107,26,.25); }
.ladder-row.done { opacity: 1; background: #F0FFF9; border-color: #9BE2C8; }
.ladder-icon { font-size: 20px; width: 28px; text-align: center; flex: none; }
.ladder-name { font-size: 12px; font-weight: 900; flex: 1; }
.ladder-status { font-size: 8.5px; font-weight: 900; letter-spacing: .04em; padding: 4px 7px; border-radius: 999px; background: #EEE6D9; color: #7A6A55; }
.ladder-row.current .ladder-status { background: var(--orange); color: #fff; }
.ladder-row.done .ladder-status { background: #C9F7E5; color: #0C7A55; }

/* ---------------- team ---------------- */
#screen-team { background: var(--cream); }
.team-summary {
  background: linear-gradient(135deg, var(--navy-2), var(--navy));
  color: #fff;
  border: 3px solid var(--navy);
  border-radius: 20px;
  padding: 14px;
  box-shadow: 0 5px 0 var(--navy);
  margin-top: 6px;
  display: flex;
  align-items: center;
  gap: 12px;
}
.ts-badge {
  width: 64px; height: 64px; border-radius: 18px;
  background: linear-gradient(180deg, var(--orange-2), var(--orange));
  border: 2.5px solid var(--navy);
  display: grid; place-items: center;
  font-size: 32px;
  box-shadow: inset 0 -5px 0 rgba(0,0,0,.15);
  flex: none;
}
.ts-info { flex: 1; min-width: 0; }
.ts-name { font-size: 18px; font-weight: 900; line-height: 1; }
.ts-sub { font-size: 9.5px; color: #B9CBE4; margin-top: 3px; font-weight: 700; }
.ts-overall { text-align: center; flex: none; }
.ts-overall b { display: block; font-size: 26px; color: var(--gold); line-height: 1; }
.ts-overall span { font-size: 7.5px; letter-spacing: .12em; font-weight: 900; color: #B9CBE4; }
.team-hint { margin-top: 10px; font-size: 10.5px; line-height: 1.4; background: #FFFBF2; border-style: dashed; }
.team-hint b { color: var(--orange); }
.team-list { display: flex; flex-direction: column; gap: 11px; margin-top: 12px; }
.player-card {
  background: #fff;
  border: 2.5px solid var(--navy);
  border-radius: 18px;
  padding: 11px;
  box-shadow: var(--shadow-soft);
}
.player-head { display: flex; align-items: center; gap: 10px; }
.avatar { width: 56px; height: 56px; border-radius: 50%; overflow: hidden; border: 2.5px solid var(--navy); background: var(--cream-2); flex: none; }
.avatar svg { width: 100%; height: 100%; }
.player-id { flex: 1; min-width: 0; }
.player-name { font-size: 15px; font-weight: 900; line-height: 1.1; }
.player-role { font-size: 9px; color: var(--muted); font-weight: 700; margin-top: 2px; }
.player-ovr { text-align: center; flex: none; background: var(--cream); border: 2px solid var(--navy); border-radius: 11px; padding: 4px 8px; }
.player-ovr b { display: block; font-size: 18px; line-height: 1; }
.player-ovr span { font-size: 6.5px; letter-spacing: .1em; font-weight: 900; color: var(--muted); }
.stat-rows { margin-top: 9px; display: flex; flex-direction: column; gap: 5px; }
.stat-row { display: flex; align-items: center; gap: 6px; }
.stat-name { width: 50px; font-size: 8.5px; font-weight: 900; letter-spacing: .03em; color: #56657E; flex: none; }
.stat-bar { flex: 1; height: 8px; border-radius: 4px; background: #EDE3D5; overflow: hidden; border: 1px solid rgba(14,27,51,.1); }
.stat-bar i { display: block; height: 100%; border-radius: 4px; background: linear-gradient(90deg, var(--orange-2), var(--orange)); transition: width .25s ease; }
.stat-bar i.high { background: linear-gradient(90deg, #59E0B6, #1FB98C); }
.stat-val { width: 20px; text-align: right; font-size: 9.5px; font-weight: 900; flex: none; }
.stat-up {
  flex: none;
  border: 2px solid var(--navy);
  background: var(--gold);
  color: var(--navy);
  border-radius: 8px;
  font-size: 9px;
  font-weight: 900;
  padding: 2px 5px;
  min-width: 46px;
  box-shadow: 0 2px 0 var(--navy);
  line-height: 1.15;
}
.stat-up:active { transform: translateY(1px); box-shadow: 0 1px 0 var(--navy); }
.stat-up small { display: block; font-size: 7px; opacity: .8; }
.stat-up.maxed { background: #E7E1D6; color: #8C8274; box-shadow: none; border-color: #B8AD9C; }

/* ---------------- segmented ---------------- */
.seg {
  display: flex;
  background: #EFE5D6;
  border: 2px solid rgba(14,27,51,.12);
  border-radius: 13px;
  padding: 3px;
  gap: 3px;
  margin: 4px 0 12px;
}
.seg button {
  flex: 1;
  border: 0;
  background: transparent;
  border-radius: 10px;
  padding: 8px 4px;
  font-size: 10.5px;
  font-weight: 900;
  color: #7B6A55;
}
.seg button.active { background: var(--navy); color: #fff; box-shadow: 0 2px 0 rgba(0,0,0,.25); }
.seg--sm { margin-top: -6px; }
.seg--sm button.active { background: var(--orange); }

/* ---------------- leaderboard ---------------- */
#screen-leaderboard { background: var(--cream); }
.lb-me {
  background: linear-gradient(135deg, #FF8A2B, var(--orange));
  border: 2.5px solid var(--navy);
  border-radius: 16px;
  padding: 10px 12px;
  color: #fff;
  display: flex;
  align-items: center;
  gap: 10px;
  box-shadow: 0 4px 0 var(--navy);
  margin-bottom: 12px;
}
.lb-me .rank { font-size: 24px; font-weight: 900; text-shadow: 0 2px 0 rgba(0,0,0,.25); }
.lb-me .info { flex: 1; min-width: 0; }
.lb-me .info b { display: block; font-size: 13px; }
.lb-me .info span { font-size: 9px; opacity: .9; }
.lb-me .xp { font-size: 12px; font-weight: 900; color: var(--gold); }
.lb-list { display: flex; flex-direction: column; gap: 6px; }
.lb-row {
  display: flex;
  align-items: center;
  gap: 9px;
  background: #fff;
  border: 2px solid rgba(14,27,51,.1);
  border-radius: 12px;
  padding: 7px 9px;
}
.lb-row.you { border: 2.5px solid var(--orange); background: #FFF4E8; }
.lb-rank { width: 25px; text-align: center; font-size: 11px; font-weight: 900; color: #8B7B66; flex: none; }
.lb-rank.top { font-size: 17px; }
.lb-av { width: 30px; height: 30px; border-radius: 50%; flex: none; display: grid; place-items: center; font-weight: 900; font-size: 11px; color: #fff; border: 2px solid var(--navy); }
.lb-name { flex: 1; min-width: 0; }
.lb-name b { display: block; font-size: 11.5px; font-weight: 900; line-height: 1.1; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.lb-name span { font-size: 8.5px; color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; display: block; }
.lb-xp { font-size: 10.5px; font-weight: 900; color: var(--navy); flex: none; }
.lb-xp small { display: block; font-size: 7px; color: var(--muted); text-align: right; }

/* ---------------- shop ---------------- */
#screen-shop { background: var(--cream); }
.shop-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.shop-card {
  background: #fff;
  border: 2.5px solid var(--navy);
  border-radius: 16px;
  padding: 10px;
  box-shadow: var(--shadow-soft);
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.shop-card.owned { background: #F2FFF9; border-color: #168A63; }
.shop-card.equipped { box-shadow: 0 0 0 3px var(--orange), var(--shadow-soft); }
.shop-preview {
  height: 86px;
  border-radius: 11px;
  border: 2px solid var(--navy);
  display: grid;
  place-items: center;
  overflow: hidden;
  position: relative;
}
.shop-preview.jersey { background: linear-gradient(160deg, #F3F8FF, #DCE8F8); }
.shop-preview.court { padding: 0; }
.shop-preview.court .mini-court { width: 100%; height: 100%; position: relative; }
.mini-court .floor { position: absolute; inset: 8px; border-radius: 5px; border: 2px solid rgba(255,255,255,.85); }
.mini-court .mid { position: absolute; left: 8px; right: 8px; top: 50%; height: 2px; background: rgba(255,255,255,.8); }
.mini-court .circle { position: absolute; width: 22px; height: 22px; border: 2px solid rgba(255,255,255,.8); border-radius: 50%; left: 50%; top: 50%; transform: translate(-50%, -50%); }
.mini-court .hoop { position: absolute; width: 20px; height: 4px; background: #FF5200; border-radius: 2px; left: 50%; transform: translateX(-50%); }
.shop-name { font-size: 11.5px; font-weight: 900; line-height: 1.15; }
.shop-tag { font-size: 7.5px; font-weight: 900; letter-spacing: .08em; color: var(--orange); }
.shop-price { display: flex; align-items: center; gap: 4px; font-size: 11px; font-weight: 900; color: var(--navy); }
.shop-card .btn { width: 100%; font-size: 10px; padding: 7px; border-radius: 9px; }
.pack-hero {
  background: linear-gradient(135deg, var(--navy-2), var(--navy));
  border: 3px solid var(--navy);
  border-radius: 20px;
  padding: 16px;
  color: #fff;
  text-align: center;
  box-shadow: 0 5px 0 var(--navy);
  margin-top: 6px;
  position: relative;
  overflow: hidden;
}
.pack-hero::after {
  content: "";
  position: absolute; left: -60%; top: 0; width: 40%; height: 100%;
  background: linear-gradient(90deg, transparent, rgba(255,255,255,.2), transparent);
  transform: skewX(-20deg);
  animation: shine 3s ease-in-out infinite;
}
.pack-hero .pack-emoji { font-size: 64px; filter: drop-shadow(0 6px 0 rgba(0,0,0,.3)); }
.pack-hero h2 { margin: 6px 0 2px; font-size: 22px; font-weight: 900; }
.pack-hero p { margin: 0 0 12px; font-size: 10.5px; color: #B9CBE4; line-height: 1.4; }
.pack-count { display: inline-flex; align-items: center; gap: 5px; background: rgba(255,255,255,.12); border-radius: 999px; padding: 5px 10px; font-size: 10px; font-weight: 900; margin-bottom: 10px; }
.pack-actions { display: flex; gap: 8px; }
.pack-actions .btn { flex: 1; font-size: 11px; }
.rarity-note { margin-top: 12px; font-size: 10px; line-height: 1.5; color: var(--muted); background: #fff; border: 2px dashed rgba(14,27,51,.18); border-radius: 12px; padding: 10px; }
.rarity-note b { color: var(--navy); }

/* ---------------- bottom nav ---------------- */
.bottom-nav {
  position: absolute;
  left: 0; right: 0; bottom: 0;
  height: calc(68px + var(--safe-b));
  padding: 6px 6px calc(4px + var(--safe-b));
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  background: #fff;
  border-top: 2.5px solid var(--navy);
  z-index: 60;
  box-shadow: 0 -4px 14px rgba(14,27,51,.08);
}
.bottom-nav button {
  border: 0;
  background: transparent;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 1px;
  color: #8B7B66;
  border-radius: 12px;
  padding: 2px;
  min-width: 0;
}
.bottom-nav button span { font-size: 19px; line-height: 1; filter: grayscale(.65); opacity: .75; }
.bottom-nav button small { font-size: 8px; font-weight: 900; letter-spacing: .01em; }
.bottom-nav button.active { color: var(--orange); background: #FFF2E6; }
.bottom-nav button.active span { filter: none; opacity: 1; transform: translateY(-1px); }

/* ---------------- game ---------------- */
#game-layer {
  position: absolute;
  inset: 0;
  z-index: 100;
  background: #0A1426;
  overflow: hidden;
}
#game-canvas { display: block; width: 100%; height: 100%; touch-action: none; }

#game-hud {
  position: absolute;
  top: 0; left: 0; right: 0;
  z-index: 5;
  padding: calc(8px + var(--safe-t)) 10px 8px;
  background: linear-gradient(180deg, rgba(6,13,26,.94) 0%, rgba(6,13,26,.82) 60%, rgba(6,13,26,0) 100%);
  pointer-events: none;
}
.hud-scoreboard { display: flex; align-items: center; gap: 8px; color: #fff; }
.hud-team { flex: 1; display: flex; align-items: center; gap: 5px; font-size: 8.5px; font-weight: 900; letter-spacing: .04em; color: #D6E3F7; min-width: 0; }
.hud-team span:last-child, .hud-team span:first-child { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.hud-them { justify-content: flex-end; }
.hud-dot { width: 8px; height: 8px; border-radius: 50%; flex: none; background: var(--orange); box-shadow: 0 0 0 2px rgba(255,255,255,.2); }
.hud-them .hud-dot { background: var(--sky); }
.hud-nums { display: flex; align-items: center; gap: 4px; font-size: 25px; font-weight: 900; line-height: 1; text-shadow: 0 2px 0 rgba(0,0,0,.4); flex: none; }
.hud-nums span:first-child { color: var(--gold); }
.hud-colon { color: rgba(255,255,255,.5); font-size: 18px; }
.hud-meta { display: flex; align-items: center; justify-content: center; gap: 7px; margin-top: 5px; }
.hud-pill {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  background: rgba(255,255,255,.1);
  border: 1.5px solid rgba(255,255,255,.18);
  border-radius: 999px;
  padding: 3px 9px;
  color: #fff;
  font-size: 12px;
  font-weight: 900;
  line-height: 1;
}
.hud-mini { font-size: 6.5px; letter-spacing: .1em; color: #A9BDD9; font-weight: 900; }
.hud-clock #hud-time { color: #fff; }
.hud-shot #hud-shot { color: var(--gold); }
.hud-shot.low { border-color: var(--red); background: rgba(255,77,94,.25); animation: pulse 1s infinite; }
.hud-shot.low #hud-shot { color: #FF8A95; }
.hud-pause {
  pointer-events: auto;
  width: 30px; height: 30px;
  border-radius: 9px;
  border: 1.5px solid rgba(255,255,255,.25);
  background: rgba(255,255,255,.1);
  color: #fff;
  font-size: 10px;
  font-weight: 900;
  display: grid; place-items: center;
}

#controls {
  position: absolute;
  left: 0; right: 0; bottom: 0;
  z-index: 6;
  padding: 0 14px calc(12px + var(--safe-b));
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  pointer-events: none;
  touch-action: none;
}
.joystick {
  pointer-events: auto;
  position: relative;
  width: 126px; height: 126px;
  border-radius: 50%;
  background: radial-gradient(circle at 50% 40%, rgba(255,255,255,.14), rgba(255,255,255,.05) 65%, rgba(255,255,255,.02));
  border: 2px solid rgba(255,255,255,.22);
  box-shadow: inset 0 0 26px rgba(0,0,0,.35);
  touch-action: none;
  flex: none;
}
.joy-ring {
  position: absolute; inset: 17px;
  border-radius: 50%;
  border: 1.5px dashed rgba(255,255,255,.18);
}
.joy-knob {
  position: absolute;
  left: 50%; top: 50%;
  width: 58px; height: 58px;
  margin: -29px 0 0 -29px;
  border-radius: 50%;
  background: linear-gradient(180deg, var(--orange-2), var(--orange));
  border: 2.5px solid var(--navy);
  box-shadow: 0 4px 0 rgba(0,0,0,.45), inset 0 2px 0 rgba(255,255,255,.35);
  color: #fff;
  display: grid; place-items: center;
  font-size: 17px;
  font-weight: 900;
  text-shadow: 0 2px 0 rgba(0,0,0,.25);
  will-change: transform;
}
.actions {
  pointer-events: auto;
  display: flex;
  flex-direction: column;
  gap: 8px;
  width: 150px;
  flex: none;
}
.action-row { display: flex; gap: 8px; }
.action-btn {
  flex: 1;
  border: 2.5px solid var(--navy);
  border-radius: 16px;
  color: #fff;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 1px;
  height: 58px;
  font-weight: 900;
  text-shadow: 0 2px 0 rgba(14,27,51,.3);
  box-shadow: 0 4px 0 #07101F, inset 0 2px 0 rgba(255,255,255,.25);
  touch-action: manipulation;
  transition: transform .06s ease, box-shadow .06s ease;
}
.action-btn:active, .action-btn.pressed { transform: translateY(3px); box-shadow: 0 1px 0 #07101F, inset 0 2px 0 rgba(255,255,255,.25); }
.action-btn .a-icon { font-size: 17px; line-height: 1; }
