/* ---------------- animations ---------------- */
@keyframes twinkle { 0%,100% { opacity: .25; transform: scale(.9); } 50% { opacity: .8; transform: scale(1.1); } }
@keyframes shine { 0% { left: -70%; } 55%, 100% { left: 130%; } }
@keyframes wiggle { 0%,100% { transform: rotate(-5deg); } 50% { transform: rotate(6deg); } }
@keyframes floaty { 0%,100% { transform: translateY(0) rotate(-12deg); } 50% { transform: translateY(-7px) rotate(-8deg); } }
@keyframes pulse { 0%,100% { transform: scale(1); } 50% { transform: scale(1.06); } }
@keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
@keyframes pop { from { transform: scale(.9); opacity: 0; } to { transform: scale(1); opacity: 1; } }
@keyframes tipIn { from { opacity: 0; transform: translate(-50%, 8px); } to { opacity: 1; transform: translate(-50%, 0); } }
@keyframes trophy { 0%,100% { transform: rotate(-4deg) scale(1); } 50% { transform: rotate(4deg) scale(1.06); } }
@keyframes fall { to { transform: translateY(110vh) rotate(720deg); opacity: .2; } }
@keyframes packOpen { to { transform: scale(1.08) rotate(3deg); opacity: 0; } }

