  g.updateActiveLogic=()=>{}; g.updateUserPlayer=function(p,dt){ this.updateAI(p,dt); };
  const counts={shoot:[0,0],pass:[0,0],steal:[0,0],make:[0,0],attempt:[0,0]};
  const os=g.shoot.bind(g); g.shoot=function(p,ai){ counts.shoot[p.team]++; counts.attempt[p.team]++; return os(p,ai); };
  const op=g.pass.bind(g); g.pass=function(p,ai){ counts.pass[p.team]++; return op(p,ai); };
  const ost=g.attemptSteal.bind(g); g.attemptSteal=function(p,t,ai){ counts.steal[p.team]++; return ost(p,t,ai); };
  const before={makes:g.makes};
  let lastCarrier=null,lastPos=null,stall=0,maxStall=0,stallTeam=null,stallPos=null;
  const samples=[];
  for(let i=0;i<7200;i++){
    g.update(1/60);
    if(i%60===0){
      const c=g.ball.carrier;
      if(c){ const d=lastPos?Math.hypot(c.pos.x-lastPos.x,c.pos.y-lastPos.y):999; if(c===lastCarrier && d<26){stall++; if(stall>maxStall){maxStall=stall;stallTeam=c.team;stallPos={x:Math.round(c.pos.x),y:Math.round(c.pos.y)};}} else stall=0; lastCarrier=c; lastPos={x:c.pos.x,y:c.pos.y}; }
      samples.push({t:120-Math.round(g.time),s:[...g.score],c:c?{team:c.team,x:Math.round(c.pos.x),y:Math.round(c.pos.y)}:null});
    }
    if(g.state==='ended') break;
  }
  return {state:g.state,score:g.score,time:g.time,counts,maxStall,stallTeam,stallPos,samples:samples.filter((_,i)=>i%10===0)};
})()" 2>&1 | head -60

